export type ExamType = 'WAEC' | 'NECO' | 'JAMB';

export interface Subject {
  id: string;
  name: string;
  exam: ExamType;
}

export interface Topic {
  id: string;
  subjectId: string;
  title: string;
  description: string;
  subtopics: Subtopic[];
}

export interface Subtopic {
  id: string;
  title: string;
  content: string;
}

export interface UserProfile {
  name: string;
  email: string;
  exams: ExamType[];
  selectedSubjects: Record<ExamType, string[]>;
  examDates: Record<ExamType, string>;
  weakSubjects: string[];
}

export interface Message {
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

