}

import { GoogleGenAI, Type } from "@google/genai";
import { ExamType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getTutorResponse = async (
  message: string, 
  examType: ExamType, 
  chatHistory: { role: 'user' | 'assistant', content: string }[]
) => {
  const model = 'gemini-3-flash-preview';

  const systemInstruction = examType === 'JAMB' 
    ? `You are a specialized JAMB (UTME) tutor. Focus on speed, accuracy, shortcuts, and elimination methods. Be concise. Provide JAMB-specific tips for every explanation.`
    : `You are a specialized ${examType} tutor for Nigerian secondary students. Focus on detailed conceptual explanations, theory requirements, and official marking schemes. Help students understand the 'why' behind answers.`;

  const contents = [
    ...chatHistory.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content }]
    })),
    { role: 'user', parts: [{ text: message }] }
  ];

  try {
    const response = await ai.models.generateContent({
      model,
      contents: contents as any,
      config: {
        systemInstruction,
        temperature: 0.7,
      }
    });
    return response.text || "I'm sorry, I couldn't generate a response. Please try again.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "An error occurred while connecting to the AI Tutor. Please check your connection.";
  }
};

export const analyzeEssay = async (
  question: string,
  answer: string,
  examType: ExamType
) => {
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Analyze this student's response for a ${examType} theory/essay question.
    Question: ${question}
    Student Answer: ${answer}

    Provide feedback in the following JSON format:
    {
      "score": number (0-100),
      "feedback": "string summarizing performance",
      "missingPoints": ["string", "string"],
      "modelAnswer": "string showing a perfect response"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING },
            missingPoints: { type: Type.ARRAY, items: { type: Type.STRING } },
            modelAnswer: { type: Type.STRING }
          },
          required: ["score", "feedback", "missingPoints", "modelAnswer"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Analysis Error:", error);
    return null;
  }
};

export const getSmartStudyPlan = async (profile: any) => {
  const model = 'gemini-3-flash-preview';
  const prompt = `Create a daily study plan for a Nigerian student preparing for: ${profile.exams.join(', ')}. 
  Subjects: ${Object.values(profile.selectedSubjects).flat().join(', ')}.
  Weak subjects: ${profile.weakSubjects.join(', ')}.
  Provide a list of 5 tasks with time, subject, and task description.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              time: { type: Type.STRING },
              subject: { type: Type.STRING },
              task: { type: Type.STRING }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || '[]');
  } catch (error) {
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { UserProfile, ExamType } from './types';
import Dashboard from './components/Dashboard';
import Onboarding from './components/Onboarding';
import AITutor from './components/AITutor';
import QuestionBank from './components/QuestionBank';
import EssayCoach from './components/EssayCoach';
import CBTPractice from './components/CBTPractice';
import SubjectsList from './components/SubjectsList';
import ProgressTracker from './components/ProgressTracker';
import { Home, BookOpen, MessageSquare, HelpCircle, User, BarChart2 } from 'lucide-react';

const App: React.FC = () => {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<'home' | 'subjects' | 'tutor' | 'practice' | 'progress'>('home');
  const [showEssayCoach, setShowEssayCoach] = useState(false);
  const [showCBT, setShowCBT] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('examace_profile');
    if (saved) {
      setProfile(JSON.parse(saved));
    }
  }, []);

  const handleOnboardingComplete = (newProfile: UserProfile) => {
    setProfile(newProfile);
    localStorage.setItem('examace_profile', JSON.stringify(newProfile));
  };

  if (!profile) {
    return <Onboarding onComplete={handleOnboardingComplete} />;
  }

  const renderContent = () => {
    if (showEssayCoach) return <EssayCoach onBack={() => setShowEssayCoach(false)} profile={profile} />;
    if (showCBT) return <CBTPractice onBack={() => setShowCBT(false)} profile={profile} />;

    switch (activeTab) {
      case 'home':
        return <Dashboard 
          profile={profile} 
          onNavigate={(tab: any) => setActiveTab(tab)}
          onStartEssay={() => setShowEssayCoach(true)}
          onStartCBT={() => setShowCBT(true)}
        />;
      case 'subjects':
        return <SubjectsList profile={profile} />;
      case 'tutor':
        return <AITutor profile={profile} />;
      case 'practice':
        return <QuestionBank profile={profile} onStartEssay={() => setShowEssayCoach(true)} onStartCBT={() => setShowCBT(true)} />;
      case 'progress':
        return <ProgressTracker profile={profile} />;
      default:
        return <Dashboard profile={profile} onNavigate={(tab: any) => setActiveTab(tab)} onStartEssay={() => setShowEssayCoach(true)} onStartCBT={() => setShowCBT(true)} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col max-w-md mx-auto shadow-xl relative pb-20">
      <header className="bg-white border-b px-4 py-3 sticky top-0 z-10 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold">A</div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">ExamAce <span className="text-blue-600">AI</span></h1>
        </div>
        <button className="p-2 hover:bg-slate-100 rounded-full transition-colors">
          <User className="w-5 h-5 text-slate-600" />
        </button>
      </header>

      <main className="flex-1 overflow-y-auto custom-scrollbar">
        {renderContent()}
      </main>

      <nav className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-md bg-white border-t px-2 py-2 flex justify-around items-center z-20 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
        <NavButton active={activeTab === 'home'} onClick={() => {setActiveTab('home'); setShowEssayCoach(false); setShowCBT(false);}} icon={<Home className="w-5 h-5" />} label="Home" />
        <NavButton active={activeTab === 'subjects'} onClick={() => {setActiveTab('subjects'); setShowEssayCoach(false); setShowCBT(false);}} icon={<BookOpen className="w-5 h-5" />} label="Study" />
        <NavButton active={activeTab === 'tutor'} onClick={() => {setActiveTab('tutor'); setShowEssayCoach(false); setShowCBT(false);}} icon={<MessageSquare className="w-5 h-5" />} label="AI Tutor" />
        <NavButton active={activeTab === 'practice'} onClick={() => {setActiveTab('practice'); setShowEssayCoach(false); setShowCBT(false);}} icon={<HelpCircle className="w-5 h-5" />} label="Practice" />
        <NavButton active={activeTab === 'progress'} onClick={() => {setActiveTab('progress'); setShowEssayCoach(false); setShowCBT(false);}} icon={<BarChart2 className="w-5 h-5" />} label="Stats" />
      </nav>
    </div>
  );
};

const NavButton: React.FC<{ active: boolean; onClick: () => void; icon: React.ReactNode; label: string }> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 transition-colors px-3 py-1 rounded-lg ${active ? 'text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
  >
    {icon}
    <span className="text-[10px] font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState } from 'react';
import { UserProfile, ExamType } from '../types';
import { SUBJECTS_LIST, EXAM_METADATA } from '../constants';
import { ArrowRight, ChevronLeft } from 'lucide-react';

interface Props {
  onComplete: (profile: UserProfile) => void;
}

const Onboarding: React.FC<Props> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<Partial<UserProfile>>({
    name: '',
    email: '',
    exams: [],
    selectedSubjects: { WAEC: [], NECO: [], JAMB: [] },
    examDates: { WAEC: '', NECO: '', JAMB: '' },
    weakSubjects: []
  });

  const updateExams = (exam: ExamType) => {
    const current = formData.exams || [];
    if (current.includes(exam)) {
      setFormData({ ...formData, exams: current.filter(e => e !== exam) });
    } else {
      setFormData({ ...formData, exams: [...current, exam] });
    }
  };

  const updateSubjects = (exam: ExamType, subject: string) => {
    const subs = { ...formData.selectedSubjects } as Record<ExamType, string[]>;
    if (subs[exam].includes(subject)) {
      subs[exam] = subs[exam].filter(s => s !== subject);
    } else {
      subs[exam] = [...subs[exam], subject];
    }
    setFormData({ ...formData, selectedSubjects: subs });
  };

  const handleNext = () => setStep(step + 1);
  const handleBack = () => setStep(step - 1);

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 max-w-md mx-auto">
      {step > 1 && (
        <button onClick={handleBack} className="mb-8 p-2 -ml-2 hover:bg-slate-100 rounded-full w-fit">
          <ChevronLeft className="w-6 h-6 text-slate-600" />
        </button>
      )}

      {step === 1 && (
        <div className="flex-1 flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="mb-10 text-center">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl font-bold mx-auto mb-4">A</div>
            <h1 className="text-3xl font-bold text-slate-900 mb-2">Welcome to ExamAce</h1>
            <p className="text-slate-500">Your AI-powered guide to smashing WAEC, NECO & JAMB exams.</p>
          </div>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">Full Name</label>
              <input 
                type="text" 
                className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-blue-500 outline-none transition-all"
                placeholder="Abiola Johnson"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">Email / Phone</label>
              <input 
                type="text" 
                className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-blue-500 outline-none transition-all"
                placeholder="example@mail.com"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          </div>
          <button 
            disabled={!formData.name || !formData.email}
            onClick={handleNext}
            className="mt-auto w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-2 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            Get Started <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      )}

      {step === 2 && (
        <div className="flex-1 flex flex-col animate-in fade-in slide-in-from-right-4 duration-500">
          <h2 className="text-2xl font-bold text-slate-900 mb-2">What are you writing?</h2>
          <p className="text-slate-500 mb-8">You can select multiple exams if you're taking more than one.</p>

          <div className="space-y-4">
            {(['WAEC', 'NECO', 'JAMB'] as ExamType[]).map(exam => (
              <button 
                key={exam}
                onClick={() => updateExams(exam)}
                className={`w-full p-6 rounded-2xl border-2 text-left transition-all ${
                  formData.exams?.includes(exam) 
                    ? 'border-blue-600 bg-blue-50' 
                    : 'border-slate-100 bg-white hover:border-slate-200'
                }`}
              >
                <h3 className="text-xl font-bold text-slate-900">{exam}</h3>
                <p className="text-slate-500 text-sm">{EXAM_METADATA[exam].fullName}</p>
              </button>
            ))}
          </div>

          <button 
            disabled={!formData.exams?.length}
            onClick={handleNext}
            className="mt-auto w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-blue-700 disabled:opacity-50 transition-all"
          >
            Continue
          </button>
        </div>
      )}

      {step === 3 && (
        <div className="flex-1 flex flex-col animate-in fade-in slide-in-from-right-4 duration-500">
          <h2 className="text-2xl font-bold text-slate-900 mb-2">Select Your Subjects</h2>
          <p className="text-slate-500 mb-6">Pick the subjects you'll be writing in your selected exams.</p>

          <div className="flex-1 overflow-y-auto space-y-6 pr-1 custom-scrollbar">
            {formData.exams?.map(exam => (
              <div key={exam}>
                <h3 className="font-bold text-blue-600 mb-3 flex items-center gap-2">
                  <span className="w-1.5 h-6 bg-blue-600 rounded-full"></span>
                  {exam} Subjects
                </h3>
                <div className="grid grid-cols-2 gap-2">
                  {SUBJECTS_LIST.map(subject => (
                    <button 
                      key={subject}
                      onClick={() => updateSubjects(exam, subject)}
                      className={`p-3 text-xs font-semibold rounded-xl border transition-all text-center ${
                        formData.selectedSubjects?.[exam].includes(subject)
                          ? 'bg-blue-600 text-white border-blue-600 shadow-md'
                          : 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100'
                      }`}
                    >
                      {subject}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>

          <button 
            onClick={() => onComplete(formData as UserProfile)}
            className="mt-8 w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-blue-700 transition-all"
          >
            Finalize My Profile
          </button>
        </div>
      )}
    </div>
  );
};

export default Onboarding;

import React, { useState, useRef, useEffect } from 'react';
import { UserProfile, Message, ExamType } from '../types';
import { getTutorResponse } from '../services/geminiService';
import { Send, Bot, User, Loader2, Sparkles, ChevronDown } from 'lucide-react';

interface Props {
  profile: UserProfile;
}

const AITutor: React.FC<Props> = ({ profile }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'assistant', 
      content: `Hello ${profile.name.split(' ')[0]}! I'm your ExamAce AI Tutor. Which exam are we prepping for right now?`, 
      timestamp: Date.now() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [activeMode, setActiveMode] = useState<ExamType>(profile.exams[0]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = { role: 'user', content: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    const history = messages.slice(-6).map(m => ({ role: m.role, content: m.content }));
    const response = await getTutorResponse(input, activeMode, history);

    setMessages(prev => [...prev, { 
      role: 'assistant', 
      content: response, 
      timestamp: Date.now() 
    }]);
    setIsTyping(false);
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] bg-slate-50 relative">
      {/* Mode Selector */}
      <div className="bg-white border-b px-4 py-2 flex items-center justify-between z-10 sticky top-0">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-blue-100 flex items-center justify-center">
            <Sparkles className="w-4 h-4 text-blue-600" />
          </div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Teaching Mode</p>
            <div className="flex items-center gap-1 group cursor-pointer">
              <span className="font-bold text-slate-800 text-sm">{activeMode} Guide</span>
              <ChevronDown className="w-3 h-3 text-slate-500" />
            </div>
          </div>
        </div>
        <div className="flex gap-1">
          {profile.exams.map(exam => (
            <button 
              key={exam}
              onClick={() => setActiveMode(exam)}
              className={`px-3 py-1 text-[10px] font-bold rounded-full border transition-all ${
                activeMode === exam 
                ? 'bg-blue-600 text-white border-blue-600' 
                : 'bg-white text-slate-500 border-slate-200'
              }`}
            >
              {exam}
            </button>
          ))}
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex gap-3 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center ${
                m.role === 'user' ? 'bg-slate-200 text-slate-600' : 'bg-blue-600 text-white shadow-sm'
              }`}>
                {m.role === 'user' ? <User className="w-4 h-4" /> : <Bot className="w-4 h-4" />}
              </div>
              <div className={`p-3 rounded-2xl text-sm leading-relaxed ${
                m.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-white text-slate-800 rounded-tl-none border border-slate-100 shadow-sm'
              }`}>
                {m.content}
              </div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="flex gap-3 max-w-[85%]">
              <div className="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center shadow-sm">
                <Bot className="w-4 h-4" />
              </div>
              <div className="bg-white p-3 rounded-2xl rounded-tl-none border border-slate-100 shadow-sm flex items-center gap-2 text-slate-400">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-xs font-medium">Tutor is thinking...</span>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t">
        <div className="flex items-end gap-2 bg-slate-50 rounded-2xl p-2 border border-slate-200 focus-within:border-blue-400 focus-within:ring-1 focus-within:ring-blue-100 transition-all">
          <textarea 
            rows={1}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
            placeholder="Ask a question..."
            className="flex-1 bg-transparent px-3 py-2 outline-none text-sm resize-none"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className="w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center hover:bg-blue-700 disabled:opacity-50 transition-colors shrink-0"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
        <p className="text-[10px] text-center text-slate-400 mt-2">
          {activeMode === 'JAMB' ? '🚀 Focus on speed & tricks' : '📚 Focus on detail & theory'}
        </p>
      </div>
    </div>
  );
};

export default AITutor;

import React, { useState } from 'react';
import { UserProfile, ExamType } from '../types';
import { analyzeEssay } from '../services/geminiService';
import { ChevronLeft, Send, Sparkles, CheckCircle2, AlertCircle, RefreshCw } from 'lucide-react';

interface Props {
  onBack: () => void;
  profile: UserProfile;
}

const EssayCoach: React.FC<Props> = ({ onBack, profile }) => {
  const [question, setQuestion] = useState("Explain the process of Osmosis and its biological importance in plants.");
  const [answer, setAnswer] = useState("");
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<any>(null);

  const handleAnalyze = async () => {
    if (!answer.trim()) return;
    setIsAnalyzing(true);
    const feedback = await analyzeEssay(question, answer, 'WAEC');
    setResult(feedback);
    setIsAnalyzing(false);
  };

  const reset = () => {
    setResult(null);
    setAnswer("");
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 animate-in slide-in-from-right duration-300">
      <div className="bg-white border-b px-4 py-4 flex items-center gap-4">
        <button onClick={onBack} className="p-1 hover:bg-slate-100 rounded-lg">
          <ChevronLeft className="w-6 h-6" />
        </button>
        <h2 className="text-xl font-bold text-slate-900">Theory Coach</h2>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-10">
        {!result ? (
          <div className="space-y-6">
            <div className="bg-blue-600 p-6 rounded-2xl text-white shadow-md relative overflow-hidden">
