import React, { useState, useEffect } from 'react';
import { UserProfile, Question } from '../types';
import { MOCK_QUESTIONS } from '../constants';
import { ChevronLeft, ChevronRight, Timer, Flag, CheckCircle, Info, Sparkles } from 'lucide-react';

interface Props {
  onBack: () => void;
  profile: UserProfile;
}

const CBTPractice: React.FC<Props> = ({ onBack, profile }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [timeLeft, setTimeLeft] = useState(1200); // 20 mins for mini test
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [isFinished, setIsFinished] = useState(false);

  const questions = MOCK_QUESTIONS.filter(q => q.examType === 'JAMB');
  const currentQ = questions[currentIdx];

  useEffect(() => {
    if (timeLeft > 0 && !isFinished) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    } else if (timeLeft === 0) {
      setIsFinished(true);
    }
  }, [timeLeft, isFinished]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleFinish = () => {
    if (confirm("Are you sure you want to submit?")) {
      setIsFinished(true);
    }
  };

  if (isFinished) {
    const score = questions.reduce((acc, q) => acc + (answers[q.id] === q.correctAnswer ? 1 : 0), 0);
    return (
      <div className="p-6 space-y-8 text-center animate-in zoom-in-95 duration-500">
        <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto">
          <CheckCircle className="w-10 h-10" />
        </div>
        <div>
          <h2 className="text-3xl font-bold text-slate-900">Exam Results</h2>
          <p className="text-slate-500 mt-2">JAMB UTME Mock (Mini)</p>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="p-4 rounded-2xl bg-slate-50 border border-slate-100">
            <p className="text-xs font-bold text-slate-400 uppercase">Score</p>
            <p className="text-2xl font-bold text-slate-900">{score} / {questions.length}</p>
          </div>
          <div className="p-4 rounded-2xl bg-slate-50 border border-slate-100">
            <p className="text-xs font-bold text-slate-400 uppercase">Speed</p>
            <p className="text-2xl font-bold text-slate-900">12s / q</p>
          </div>
        </div>
        <div className="space-y-4">
          <h3 className="font-bold text-slate-900 text-left px-1">Detailed Explanation</h3>
          {questions.map((q, i) => (
            <div key={q.id} className="text-left p-4 rounded-2xl border border-slate-100 bg-white space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-400">Question {i + 1}</span>
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${answers[q.id] === q.correctAnswer ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
                  {answers[q.id] === q.correctAnswer ? 'CORRECT' : 'WRONG'}
                </span>
              </div>
              <p className="text-sm font-medium text-slate-800">{q.text}</p>
              <div className="p-3 rounded-xl bg-blue-50 text-blue-700 text-xs flex gap-2">
                <Sparkles className="w-4 h-4 shrink-0" />
                <span><span className="font-bold">AI Tip:</span> {q.explanation}</span>
              </div>
            </div>
          ))}
        </div>
        <button onClick={onBack} className="w-full bg-slate-900 text-white py-4 rounded-xl font-bold">Back to Dashboard</button>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-white">
      {/* CBT Header */}
      <div className="bg-emerald-600 p-4 text-white flex items-center justify-between shadow-md">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white/20 rounded-lg flex items-center justify-center font-bold">J</div>
          <div>
            <h2 className="font-bold text-sm">JAMB Mock Test</h2>
            <p className="text-[10px] text-emerald-100">Mathematics • 2023</p>
          </div>
        </div>
        <div className="flex items-center gap-2 bg-white/20 px-3 py-1.5 rounded-full border border-white/30">
          <Timer className="w-4 h-4" />
          <span className="font-mono font-bold">{formatTime(timeLeft)}</span>
        </div>
      </div>

      {/* Question Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        <div className="flex items-center justify-between">
          <span className="px-3 py-1 bg-slate-100 text-slate-600 rounded-lg text-xs font-bold">Question {currentIdx + 1} of {questions.length}</span>
          <button className="text-slate-400 hover:text-red-500 transition-colors">
            <Flag className="w-5 h-5" />
          </button>
        </div>

        <p className="text-lg font-medium text-slate-800 leading-relaxed">
          {currentQ.text}
        </p>

        <div className="space-y-3">
          {currentQ.options?.map((opt, i) => (
            <button 
              key={i}
              onClick={() => setAnswers({...answers, [currentQ.id]: opt})}
              className={`w-full p-4 rounded-2xl border-2 text-left transition-all flex items-center gap-4 ${
                answers[currentQ.id] === opt 
                ? 'border-emerald-500 bg-emerald-50' 
                : 'border-slate-100 bg-slate-50 hover:border-slate-200'
              }`}
            >
              <div className={`w-8 h-8 rounded-full border flex items-center justify-center font-bold text-sm ${
                answers[currentQ.id] === opt ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-400 border-slate-200'
              }`}>
                {String.fromCharCode(65 + i)}
              </div>
              <span className={`font-semibold ${answers[currentQ.id] === opt ? 'text-emerald-900' : 'text-slate-700'}`}>
                {opt}
              </span>
            </button>
          ))}
        </div>
      </div>

      {/* CBT Footer Nav */}
      <div className="p-4 border-t grid grid-cols-2 gap-3 bg-white">
        <button 
          disabled={currentIdx === 0}
          onClick={() => setCurrentIdx(currentIdx - 1)}
          className="py-4 border-2 border-slate-100 rounded-xl font-bold text-slate-400 disabled:opacity-30 flex items-center justify-center gap-2"
        >
          <ChevronLeft className="w-5 h-5" /> Previous
        </button>
        {currentIdx === questions.length - 1 ? (
          <button 
            onClick={handleFinish}
            className="py-4 bg-emerald-600 text-white rounded-xl font-bold flex items-center justify-center gap-2 shadow-lg"
          >
            Submit Exam <CheckCircle className="w-5 h-5" />
          </button>
        ) : (
          <button 
            onClick={() => setCurrentIdx(currentIdx + 1)}
            className="py-4 bg-slate-900 text-white rounded-xl font-bold flex items-center justify-center gap-2"
          >
            Next <ChevronRight className="w-5 h-5" />
          </button>
        )}
      </div>

      <div className="px-4 py-3 bg-slate-50 flex gap-1 overflow-x-auto border-t">
        {questions.map((q, i) => (
          <button 
            key={q.id}
            onClick={() => setCurrentIdx(i)}
            className={`min-w-[40px] h-10 rounded-lg text-xs font-bold border transition-all ${
              currentIdx === i 
              ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm scale-110 z-10' 
              : answers[q.id] 
                ? 'bg-emerald-100 text-emerald-700 border-emerald-200' 
                : 'bg-white text-slate-400 border-slate-200'
            }`}
          >
            {i + 1}
          </button>
        ))}
      </div>
    </div>
  );
};

