          profile={profile!} 
          onNavigate={(tab: any) => setActiveTab(tab)}
          onStartEssay={() => setShowEssayCoach(true)}
          onStartCBT={() => setShowCBT(true)}
          onShowContact={() => setShowContact(true)}
        />;
      case 'subjects':
        return <SubjectsList profile={profile!} />;
      case 'tutor':
        return <AITutor profile={profile!} />;
      case 'practice':
        return <QuestionBank profile={profile!} onStartEssay={() => setShowEssayCoach(true)} onStartCBT={() => setShowCBT(true)} />;
      case 'progress':
        return <ProgressTracker profile={profile!} />;
      default:
        return <Dashboard profile={profile!} onNavigate={(tab: any) => setActiveTab(tab)} onStartEssay={() => setShowEssayCoach(true)} onStartCBT={() => setShowCBT(true)} onShowContact={() => setShowContact(true)} />;
