// Always use const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getTutorResponse = async (
  message: string, 
  examType: ExamType, 
  chatHistory: { role: 'user' | 'assistant', content: string }[]
) => {
  const model = 'gemini-3-flash-preview';

  const systemInstruction = examType === 'JAMB' 
    ? `You are a specialized JAMB (UTME) tutor. Focus on speed, accuracy, shortcuts, and elimination methods. Be concise. Provide JAMB-specific tips for every explanation.`
    : `You are a specialized ${examType} tutor for Nigerian secondary students. Focus on detailed conceptual explanations, theory requirements, and official marking schemes. Help students understand the 'why' behind answers.`;

  const contents = [
    ...chatHistory.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content }]
    })),
    { role: 'user', parts: [{ text: message }] }
  ];

  try {
    const response = await ai.models.generateContent({
      model,
      contents: contents as any,
      config: {
        systemInstruction,
        temperature: 0.7,
      }
    });
    // Extracting text from response.text property
    return response.text || "I'm sorry, I couldn't generate a response. Please try again.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "An error occurred while connecting to the AI Tutor. Please check your connection.";
  }
};

export const analyzeEssay = async (
  question: string,
  answer: string,
  examType: ExamType
) => {
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Analyze this student's response for a ${examType} theory/essay question.
    Question: ${question}
    Student Answer: ${answer}

    Provide feedback in the following JSON format:
    {
      "score": number (0-100),
      "feedback": "string summarizing performance",
      "missingPoints": ["string", "string"],
      "modelAnswer": "string showing a perfect response"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING },
            missingPoints: { type: Type.ARRAY, items: { type: Type.STRING } },
            modelAnswer: { type: Type.STRING }
          },
          required: ["score", "feedback", "missingPoints", "modelAnswer"]
        }
      }
    });

    // Extracting text from response.text property
    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Analysis Error:", error);
    return null;
  }
};

