  const handleFinish = () => {
    if (confirm("Are you sure you want to submit?")) {
      setIsFinished(true);
    }
  };

  if (isFinished) {
    const score = questions.reduce((acc, q) => acc + (answers[q.id] === q.correctAnswer ? 1 : 0), 0);
    const timeSpent = 1200 - timeLeft;
    const avgSpeed = Math.round(timeSpent / questions.length);

    return (
      <div className="p-6 space-y-8 text-center animate-in zoom-in-95 duration-500 max-w-md mx-auto">
        <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto shadow-inner">
