              }`}>
                {String.fromCharCode(65 + i)}
              </div>
              <span className={`font-semibold ${answers[currentQ.id] === opt ? 'text-emerald-900' : 'text-slate-700'}`}>
                {opt}
              </span>
            </button>
          ))}
        </div>
      </div>

      {/* CBT Footer Nav */}
      <div className="p-4 border-t grid grid-cols-2 gap-3 bg-white">
