        {currentIdx === questions.length - 1 ? (
          <button 
            onClick={handleFinish}
            className="py-4 bg-emerald-600 text-white rounded-xl font-bold flex items-center justify-center gap-2 shadow-lg"
          >
            Submit Exam <CheckCircle className="w-5 h-5" />
          </button>
        ) : (
          <button 
            onClick={() => setCurrentIdx(currentIdx + 1)}
            className="py-4 bg-slate-900 text-white rounded-xl font-bold flex items-center justify-center gap-2"
          >
            Next <ChevronRight className="w-5 h-5" />
          </button>
        )}
      </div>

      <div className="px-4 py-3 bg-slate-50 flex gap-1 overflow-x-auto border-t custom-scrollbar">
        {questions.map((q, i) => (
          <button 
            key={q.id}
            onClick={() => setCurrentIdx(i)}
            className={`min-w-[40px] h-10 rounded-lg text-xs font-bold border transition-all ${
              currentIdx === i 
              ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm scale-110 z-10' 
              : answers[q.id] 
                ? 'bg-emerald-100 text-emerald-700 border-emerald-200' 
                : 'bg-white text-slate-400 border-slate-200'
            }`}
          >
            {i + 1}
          </button>
        ))}
      </div>
    </div>
  );
};

