export const getTutorResponse = async (
  message: string, 
  examType: ExamType, 
  subject: string,
  chatHistory: { role: 'user' | 'assistant', content: string }[]
) => {
  const model = 'gemini-3-flash-preview';

  // Layer 1: Safety & Ethics
  const safetyLayer = "You are DEMO – SSCE Exam Tutor. You must respect exam ethics and integrity. NEVER provide real-time exam answers or support malpractice. If asked for answers to a live ongoing exam, politely refuse and offer to explain the underlying concepts instead.";

  // Layer 2: Exam-type (WAEC/NECO/JAMB base logic)
  const examLayer = examType === 'JAMB' 
    ? "As a JAMB coach, prioritize speed, accuracy, and CBT mastery. Use the 40-60s per question logic."
    : `As a ${examType} mentor, prioritize deep understanding, structure, and examiner-style theory answers.`;

  // Layer 3: Subject-specific prompt
  const baseSubject = subject.includes('Government') ? 'Government' : subject;
  const subjectPromptObj = SUBJECT_PROMPTS[baseSubject] || SUBJECT_PROMPTS['Mathematics']; // Default to Maths style logic if unknown
  const subjectLayer = examType === 'JAMB' ? subjectPromptObj.JAMB : subjectPromptObj.WAEC;

  const systemInstruction = `${safetyLayer}\n\n${examLayer}\n\n${subjectLayer}`;

  const contents = [
    ...chatHistory.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content }]
    })),
    { role: 'user', parts: [{ text: message }] }
  ];

  try {
    const response = await ai.models.generateContent({
      model,
      contents: contents as any,
      config: {
        systemInstruction,
        temperature: 0.6,
      }
    });
    return response.text || "I'm sorry, I couldn't generate a response. Please try again.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "An error occurred while connecting to the AI Tutor. Please check your connection.";
  }
};

export const analyzeEssay = async (
  question: string,
  answer: string,
  examType: ExamType
) => {
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Analyze this student's response for a ${examType} theory/essay question as a Digital Exam Mentor.
    Question: ${question}
    Student Answer: ${answer}

    Evaluation Criteria:
    - Content Accuracy (40%): Correct facts, relevant points.
    - Structure & Organization (25%): Intro, flow, conclusion.
    - Language & Expression (20%): Grammar, clarity, vocabulary.
    - Exam Relevance (15%): Answers exact question using examiner terms.

    Provide feedback in JSON format:
    {
      "score": number (0-100),
      "feedback": "overall summary",
      "strengths": ["point 1", "point 2"],
      "weakAreas": ["point 1", "point 2"],
      "suggestions": ["specific actionable tip 1", "tip 2"],
      "modelAnswer": "perfectly structured examiner-style response"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weakAreas: { type: Type.ARRAY, items: { type: Type.STRING } },
            suggestions: { type: Type.ARRAY, items: { type: Type.STRING } },
            modelAnswer: { type: Type.STRING }
          },
          required: ["score", "feedback", "strengths", "weakAreas", "suggestions", "modelAnswer"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Analysis Error:", error);
    return null;
  }
};

export const getSmartStudyPlan = async (profile: any) => {
  const model = 'gemini-3-flash-preview';
  const prompt = `Create a daily study plan for a Nigerian student. 
  Exams: ${profile.exams.join(', ')}. 
  Subjects: ${Object.values(profile.selectedSubjects).flat().join(', ')}.
  Weak subjects (Prioritize these): ${profile.weakSubjects.join(', ')}.
  Suggest specific topics from the official ${profile.exams[0]} syllabus.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              time: { type: Type.STRING },
              subject: { type: Type.STRING },
              task: { type: Type.STRING }
            },
            propertyOrdering: ["time", "subject", "task"],
          }
        }
      }
    });
    return JSON.parse(response.text || '[]');
  } catch (error) {
    return [];
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { UserProfile, Message, ExamType } from '../types';
import { getTutorResponse } from '../services/geminiService';
import { Send, Bot, User, Loader2, Sparkles, ChevronDown, BookOpen } from 'lucide-react';

interface Props {
  profile: UserProfile;
}

const AITutor: React.FC<Props> = ({ profile }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'assistant', 
      content: `Hello ${profile.name.split(' ')[0]}! I'm your DEMO AI Tutor. Which exam and subject are we prepping for right now?`, 
      timestamp: Date.now() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [activeMode, setActiveMode] = useState<ExamType>(profile.exams[0]);
  const [activeSubject, setActiveSubject] = useState<string>(profile.selectedSubjects[profile.exams[0]][0] || 'Mathematics');
  const [showSubjectMenu, setShowSubjectMenu] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = { role: 'user', content: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    const history = messages.slice(-6).map(m => ({ role: m.role, content: m.content }));
    const response = await getTutorResponse(input, activeMode, activeSubject, history);

    setMessages(prev => [...prev, { 
      role: 'assistant', 
      content: response, 
      timestamp: Date.now() 
    }]);
    setIsTyping(false);
  };

  const handleModeChange = (mode: ExamType) => {
    setActiveMode(mode);
    const modeSubjects = profile.selectedSubjects[mode];
    if (modeSubjects && modeSubjects.length > 0) {
      setActiveSubject(modeSubjects[0]);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] bg-slate-50 relative">
      {/* Mode & Subject Selector */}
      <div className="bg-white border-b px-4 py-2 flex flex-col gap-2 z-20 sticky top-0 shadow-sm">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-blue-100 flex items-center justify-center">
              <Sparkles className="w-4 h-4 text-blue-600" />
            </div>
            <div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Exam Mode</p>
              <div className="flex gap-1">
                {profile.exams.map(exam => (
                  <button 
                    key={exam}
                    onClick={() => handleModeChange(exam)}
                    className={`px-3 py-0.5 text-[10px] font-bold rounded-full border transition-all ${
                      activeMode === exam 
                      ? 'bg-blue-600 text-white border-blue-600' 
                      : 'bg-white text-slate-500 border-slate-200'
                    }`}
                  >
                    {exam}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="text-right relative">
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Subject</p>
            <button 
              onClick={() => setShowSubjectMenu(!showSubjectMenu)}
              className="flex items-center gap-1 group cursor-pointer bg-slate-50 px-2 py-1 rounded-lg border border-slate-100"
            >
              <span className="font-bold text-slate-800 text-xs truncate max-w-[100px]">{activeSubject}</span>
              <ChevronDown className={`w-3 h-3 text-slate-500 transition-transform ${showSubjectMenu ? 'rotate-180' : ''}`} />
            </button>

            {showSubjectMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-xl shadow-xl border border-slate-100 py-2 z-30 animate-in fade-in zoom-in-95 duration-200">
                {profile.selectedSubjects[activeMode].map(subject => (
                  <button 
                    key={subject}
                    onClick={() => {
                      setActiveSubject(subject);
                      setShowSubjectMenu(false);
                    }}
                    className={`w-full text-left px-4 py-2 text-xs font-bold transition-colors hover:bg-slate-50 ${
                      activeSubject === subject ? 'text-blue-600' : 'text-slate-600'
                    }`}
                  >
                    {subject}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar" onClick={() => setShowSubjectMenu(false)}>
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex gap-3 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center ${
                m.role === 'user' ? 'bg-slate-200 text-slate-600' : 'bg-blue-600 text-white shadow-sm'
              }`}>
                {m.role === 'user' ? <User className="w-4 h-4" /> : <Bot className="w-4 h-4" />}
              </div>
              <div className={`p-3 rounded-2xl text-sm leading-relaxed ${
                m.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-white text-slate-800 rounded-tl-none border border-slate-100 shadow-sm'
              }`}>
                {m.content}
              </div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="flex gap-3 max-w-[85%]">
              <div className="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center shadow-sm">
                <Bot className="w-4 h-4" />
              </div>
              <div className="bg-white p-3 rounded-2xl rounded-tl-none border border-slate-100 shadow-sm flex items-center gap-2 text-slate-400">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-xs font-medium">Tutor is thinking...</span>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t">
        <div className="flex items-end gap-2 bg-slate-50 rounded-2xl p-2 border border-slate-200 focus-within:border-blue-400 focus-within:ring-1 focus-within:ring-blue-100 transition-all">
          <textarea 
            rows={1}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
            placeholder={`Ask about ${activeSubject}...`}
            className="flex-1 bg-transparent px-3 py-2 outline-none text-sm resize-none"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className="w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center hover:bg-blue-700 disabled:opacity-50 transition-colors shrink-0"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
        <p className="text-[10px] text-center text-slate-400 mt-2">
          {activeMode === 'JAMB' ? `🚀 JAMB ${activeSubject} mode: Focus on speed & tricks` : `📚 ${activeMode} ${activeSubject} mode: Focus on detail & theory`}
        </p>
      </div>
    </div>
  );
};

