    setIsTyping(true);

    const history = messages.slice(-6).map(m => ({ role: m.role, content: m.content }));
    const response = await getTutorResponse(input, activeMode, activeSubject, history);

    setMessages(prev => [...prev, { 
      role: 'assistant', 
      content: response, 
      timestamp: Date.now() 
    }]);
    setIsTyping(false);
  };

  const handleModeChange = (mode: ExamType) => {
    setActiveMode(mode);
    const modeSubjects = profile.selectedSubjects[mode];
    if (modeSubjects && modeSubjects.length > 0) {
      setActiveSubject(modeSubjects[0]);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] bg-slate-50 relative overflow-hidden">
      {/* Background Decorative Elements */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none">
        <div className="absolute top-10 left-10 rotate-12"><GraduationCap size={120} /></div>
        <div className="absolute bottom-20 right-10 -rotate-12"><BookOpen size={100} /></div>
      </div>

      {/* Mode & Subject Selector */}
      <div className="bg-white/80 backdrop-blur-md border-b px-4 py-3 flex flex-col gap-2 z-20 sticky top-0 shadow-sm">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-blue-700 flex items-center justify-center shadow-lg shadow-blue-100">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Studying Mode</p>
              <div className="flex gap-1.5 mt-0.5">
                {profile.exams.map(exam => (
                  <button 
                    key={exam}
                    onClick={() => handleModeChange(exam)}
                    className={`px-3 py-1 text-[10px] font-bold rounded-lg border transition-all duration-200 ${
                      activeMode === exam 
                      ? 'bg-blue-600 text-white border-blue-600 shadow-md shadow-blue-100 scale-105' 
                      : 'bg-white text-slate-500 border-slate-200 hover:border-blue-300'
                    }`}
                  >
                    {exam}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="text-right relative">
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Active Subject</p>
            <button 
              onClick={() => setShowSubjectMenu(!showSubjectMenu)}
              className="flex items-center gap-2 group cursor-pointer bg-slate-100/50 hover:bg-slate-100 px-3 py-1.5 rounded-xl border border-slate-200/50 transition-colors mt-0.5"
            >
              <span className="font-bold text-slate-800 text-xs truncate max-w-[100px]">{activeSubject}</span>
              <ChevronDown className={`w-3.5 h-3.5 text-slate-500 transition-transform duration-300 ${showSubjectMenu ? 'rotate-180' : ''}`} />
            </button>

            {showSubjectMenu && (
              <div className="absolute right-0 mt-2 w-52 bg-white rounded-2xl shadow-2xl border border-slate-100 py-2 z-30 animate-in fade-in zoom-in-95 slide-in-from-top-2 duration-200">
                <div className="px-4 py-2 border-b border-slate-50 mb-1">
                  <p className="text-[10px] font-bold text-slate-400 uppercase">Select Subject</p>
                </div>
                {profile.selectedSubjects[activeMode].map(subject => (
                  <button 
                    key={subject}
                    onClick={() => {
                      setActiveSubject(subject);
                      setShowSubjectMenu(false);
                    }}
                    className={`w-full text-left px-4 py-2.5 text-xs font-bold transition-colors hover:bg-blue-50 flex items-center justify-between ${
                      activeSubject === subject ? 'text-blue-600 bg-blue-50/50' : 'text-slate-600'
                    }`}
                  >
                    {subject}
                    {activeSubject === subject && <div className="w-1.5 h-1.5 rounded-full bg-blue-600"></div>}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar" onClick={() => setShowSubjectMenu(false)}>
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
            <div className={`flex gap-3 max-w-[90%] ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className={`w-9 h-9 rounded-2xl flex-shrink-0 flex items-center justify-center shadow-sm ${
                m.role === 'user' 
                ? 'bg-slate-200 text-slate-600' 
                : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'
              }`}>
                {m.role === 'user' ? <User className="w-5 h-5" /> : <Bot className="w-5 h-5" />}
              </div>
              <div className={`relative p-4 rounded-3xl text-[14px] leading-relaxed shadow-sm transition-all ${
                m.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none font-medium' 
                  : 'bg-white text-slate-800 rounded-tl-none border border-slate-200/50'
              }`}>
                {m.content}
                <div className={`text-[9px] mt-2 opacity-60 font-bold ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </div>
                {/* Tail Decoration */}
                <div className={`absolute top-0 w-4 h-4 ${
                  m.role === 'user' 
                  ? '-right-1 bg-blue-600 clip-path-right' 
                  : '-left-1 bg-white border-l border-t border-slate-200/50 clip-path-left'
                }`} style={{ clipPath: m.role === 'user' ? 'polygon(0 0, 100% 0, 0 100%)' : 'polygon(0 0, 100% 0, 100% 100%)' }}></div>
              </div>
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex justify-start animate-pulse">
            <div className="flex gap-3 max-w-[85%]">
              <div className="w-9 h-9 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white flex items-center justify-center shadow-md">
                <Bot className="w-5 h-5" />
              </div>
              <div className="bg-white p-4 rounded-3xl rounded-tl-none border border-slate-200/50 shadow-sm flex items-center gap-3">
                <div className="flex gap-1">
                  <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                  <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
                  <span className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
                </div>
                <span className="text-xs font-bold text-slate-400 tracking-tight">MENTOR IS THINKING...</span>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white/80 backdrop-blur-lg border-t pb-6">
        <div className="flex items-end gap-2 bg-white rounded-2xl p-2 border-2 border-slate-100 focus-within:border-blue-500 focus-within:ring-4 focus-within:ring-blue-50 transition-all duration-300 shadow-sm">
          <textarea 
            rows={1}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
            placeholder={`Ask a ${activeSubject} question...`}
            className="flex-1 bg-transparent px-4 py-3 outline-none text-sm resize-none font-medium text-slate-700"
            style={{ minHeight: '44px', maxHeight: '120px' }}
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className="w-11 h-11 bg-blue-600 text-white rounded-xl flex items-center justify-center hover:bg-blue-700 hover:scale-105 active:scale-95 disabled:opacity-50 disabled:scale-100 transition-all shadow-lg shadow-blue-200 shrink-0"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
        <div className="flex items-center justify-center gap-4 mt-3">
           <div className="h-[1px] flex-1 bg-slate-100"></div>
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
            {activeMode === 'JAMB' ? 'CBT Shortcut Mode' : 'Theory Mastery Mode'}
          </p>
           <div className="h-[1px] flex-1 bg-slate-100"></div>
        </div>
      </div>
    </div>
  );
};

