import React, { useState, useEffect } from 'react';
import { UserProfile, ExamType } from './types';
import Dashboard from './components/Dashboard';
import Onboarding from './components/Onboarding';
import AITutor from './components/AITutor';
import QuestionBank from './components/QuestionBank';
import EssayCoach from './components/EssayCoach';
import CBTPractice from './components/CBTPractice';
import SubjectsList from './components/SubjectsList';
import ProgressTracker from './components/ProgressTracker';
import LandingPage from './components/LandingPage';
import PrivacyPolicy from './components/PrivacyPolicy';
import TermsOfUse from './components/TermsOfUse';
import ContactSupport from './components/ContactSupport';
import PaymentPage from './components/PaymentPage';
import { Home, BookOpen, MessageSquare, HelpCircle, User, BarChart2, Crown } from 'lucide-react';

const App: React.FC = () => {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isStartingOnboarding, setIsStartingOnboarding] = useState(false);
  const [showPrivacy, setShowPrivacy] = useState(false);
  const [showTerms, setShowTerms] = useState(false);
  const [showContact, setShowContact] = useState(false);
  const [activeTab, setActiveTab] = useState<'home' | 'subjects' | 'tutor' | 'practice' | 'progress'>('home');
  const [showEssayCoach, setShowEssayCoach] = useState(false);
  const [showCBT, setShowCBT] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('examace_profile');
    if (saved) {
      setProfile(JSON.parse(saved));
    }
  }, []);

  const handleOnboardingComplete = (newProfile: UserProfile) => {
    const profileWithInitialPay = { ...newProfile, isPaid: false };
    setProfile(profileWithInitialPay);
    localStorage.setItem('examace_profile', JSON.stringify(profileWithInitialPay));
    setIsStartingOnboarding(false);
  };

  const handlePaymentSuccess = () => {
    setProfile(prev => {
      if (!prev) return null;
      const updated = { ...prev, isPaid: true };
      localStorage.setItem('examace_profile', JSON.stringify(updated));
      return updated;
    });
  };

  if (showPrivacy) {
    return <PrivacyPolicy onBack={() => setShowPrivacy(false)} />;
  }

  if (showTerms) {
    return <TermsOfUse onBack={() => setShowTerms(false)} />;
  }

  if (showContact) {
    return <ContactSupport onBack={() => setShowContact(false)} />;
  }

  // 1. Not onboarded yet
  if (!profile && !isStartingOnboarding) {
    return (
      <LandingPage 
        onStart={() => setIsStartingOnboarding(true)} 
        onShowPrivacy={() => setShowPrivacy(true)} 
        onShowTerms={() => setShowTerms(true)}
        onShowContact={() => setShowContact(true)}
      />
    );
  }

  // 2. Doing onboarding
  if (!profile && isStartingOnboarding) {
    return <Onboarding onComplete={handleOnboardingComplete} />;
  }

  // 3. LOCK APP UNTIL PAYMENT
  if (profile && !profile.isPaid) {
    return <PaymentPage profile={profile} onPaymentSuccess={handlePaymentSuccess} />;
  }

  const renderContent = () => {
    if (showEssayCoach) return <EssayCoach onBack={() => setShowEssayCoach(false)} profile={profile!} />;
    if (showCBT) return <CBTPractice onBack={() => setShowCBT(false)} profile={profile!} />;

    switch (activeTab) {
      case 'home':
        return <Dashboard 
          profile={profile!} 
          onNavigate={(tab: any) => setActiveTab(tab)}
          onStartEssay={() => setShowEssayCoach(true)}
          onStartCBT={() => setShowCBT(true)}
          onShowContact={() => setShowContact(true)}
        />;
      case 'subjects':
        return <SubjectsList profile={profile!} />;
      case 'tutor':
        return <AITutor profile={profile!} />;
      case 'practice':
        return <QuestionBank profile={profile!} onStartEssay={() => setShowEssayCoach(true)} onStartCBT={() => setShowCBT(true)} />;
      case 'progress':
        return <ProgressTracker profile={profile!} />;
      default:
        return <Dashboard profile={profile!} onNavigate={(tab: any) => setActiveTab(tab)} onStartEssay={() => setShowEssayCoach(true)} onStartCBT={() => setShowCBT(true)} onShowContact={() => setShowContact(true)} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col max-w-md mx-auto shadow-xl relative pb-20">
      <header className="bg-white border-b px-4 py-3 sticky top-0 z-10 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold shadow-sm">D</div>
          <div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight leading-none">DEMO</h1>
            <span className="text-blue-600 text-[9px] font-bold uppercase tracking-tighter">Digital Exam mentor</span>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {profile?.isPaid && (
            <div className="flex items-center gap-1 bg-amber-100 text-amber-700 px-2 py-1 rounded-full text-[9px] font-black border border-amber-200">
              <Crown className="w-3 h-3" />
              PREMIUM
            </div>
          )}
          <button 
            onClick={() => setShowContact(true)}
            className="p-1.5 hover:bg-slate-100 rounded-full transition-colors text-slate-500"
            title="Help & Support"
          >
            <HelpCircle className="w-5 h-5" />
          </button>
          <button className="p-1.5 hover:bg-slate-100 rounded-full transition-colors text-slate-500">
            <User className="w-5 h-5" />
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto custom-scrollbar bg-slate-50">
        {renderContent()}
      </main>

      <nav className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-md bg-white/80 backdrop-blur-lg border-t px-2 py-2 flex justify-around items-center z-20 shadow-[0_-4px_20px_rgba(0,0,0,0.05)]">
        <NavButton active={activeTab === 'home'} onClick={() => {setActiveTab('home'); setShowEssayCoach(false); setShowCBT(false);}} icon={<Home className="w-5 h-5" />} label="Home" />
        <NavButton active={activeTab === 'subjects'} onClick={() => {setActiveTab('subjects'); setShowEssayCoach(false); setShowCBT(false);}} icon={<BookOpen className="w-5 h-5" />} label="Study" />
        <NavButton active={activeTab === 'tutor'} onClick={() => {setActiveTab('tutor'); setShowEssayCoach(false); setShowCBT(false);}} icon={<MessageSquare className="w-5 h-5" />} label="AI Tutor" />
        <NavButton active={activeTab === 'practice'} onClick={() => {setActiveTab('practice'); setShowEssayCoach(false); setShowCBT(false);}} icon={<HelpCircle className="w-5 h-5" />} label="Practice" />
        <NavButton active={activeTab === 'progress'} onClick={() => {setActiveTab('progress'); setShowEssayCoach(false); setShowCBT(false);}} icon={<BarChart2 className="w-5 h-5" />} label="Stats" />
      </nav>
    </div>
  );
};

const NavButton: React.FC<{ active: boolean; onClick: () => void; icon: React.ReactNode; label: string }> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 transition-all px-3 py-1 rounded-xl ${active ? 'text-blue-600 scale-110 font-bold' : 'text-slate-400 hover:text-slate-600'}`}
  >
    {icon}
    <span className="text-[9px] uppercase tracking-tighter">{label}</span>
  </button>
);

export default App;

