    JAMB: "JAMB Literature CBT specialist. Focus on plot recall, literary devices, and distinguishing similar terms."
  },
  'Government': {
    WAEC: "WAEC Government tutor. Focus on structured bullet-point explanations of political concepts.",
    JAMB: "JAMB Government CBT coach. Focus on constitutional history and institutional functions."
  }
};

const SYLLABUS_INTEGRITY_PROMPT = `
You are an educational content generator for Nigerian secondary school examinations (WAEC, NECO, JAMB).
You must generate ONLY original exam-style practice questions.

STRICT RULES:
- NEVER copy, recall, paraphrase, or imitate any real past question.
- NEVER reference exam years (e.g., 'JAMB 2015'), paper codes, or leaked materials.
- NEVER claim questions are “official” past questions.
- All questions must be syllabus-aligned, original, and newly constructed by you.
- Label all practice outputs clearly as “exam-style practice questions”.

Target Exam Context:
If WAEC or NECO:
- Focus on understanding, explanation, structure, and marking points.
- Support theory, essay, and objective formats.
- Maintain a formal, examiner-standard tone.

If JAMB:
- Focus on CBT format.
- Emphasize speed, clarity, common traps, and option elimination.
- Keep explanations brief and time-aware.
`;

export const getTutorResponse = async (
  message: string, 
  examType: ExamType, 
  subject: string,
  chatHistory: { role: 'user' | 'assistant', content: string }[],
  image?: { data: string; mimeType: string }
) => {
  const model = 'gemini-3-pro-preview';

  const safetyLayer = "You are DEMO – Digital Exam Mentor. Respect exam integrity. NEVER provide answers to live ongoing exams.";
  const examLayer = `Current target exam: ${examType}. ${SYLLABUS_INTEGRITY_PROMPT}`;

  const baseSubject = subject.includes('Government') ? 'Government' : subject;
  const subjectPromptObj = SUBJECT_PROMPTS[baseSubject] || SUBJECT_PROMPTS['Mathematics']; 
  const subjectLayer = examType === 'JAMB' ? subjectPromptObj.JAMB : subjectPromptObj.WAEC;

  const systemInstruction = `${safetyLayer}\n\n${examLayer}\n\n${subjectLayer}${image ? '\n\nAn image of academic content (textbook, diagram, or handwriting) is provided. Analyze it carefully to help the student.' : ''}`;

  const parts: any[] = [];
  if (image) {
    parts.push({
      inlineData: {
        data: image.data,
        mimeType: image.mimeType
      }
    });
  }
  parts.push({ text: message });

  const contents = [
    ...chatHistory.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content }]
    })),
    { role: 'user', parts }
  ];

  try {
    const response = await ai.models.generateContent({
      model,
      contents: contents as any,
      config: {
        systemInstruction,
        temperature: 0.5,
      }
    });
    return response.text || "I'm sorry, I couldn't generate a response.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "An error occurred. Please check your internet connection.";
  }
};

export const analyzeEssay = async (
  question: string,
  answer: string,
  examType: ExamType
) => {
  const model = 'gemini-3-pro-preview';

  const prompt = `
    Analyze this student's response for a ${examType} theory/essay question.
    Question: ${question}
    Student Answer: ${answer}

    ${SYLLABUS_INTEGRITY_PROMPT}

    Evaluation Criteria:
    - Content Accuracy (40%): Correct facts, relevant points.
    - Structure & Organization (25%): Flow and cohesion.
    - Language & Expression (20%): Grammar and clarity.
    - Exam Relevance (15%): Use of examiner terminology.

    Provide feedback in JSON format:
    {
      "score": number (0-100),
      "feedback": "overall summary",
      "strengths": ["point 1", "point 2"],
      "weakAreas": ["point 1", "point 2"],
      "suggestions": ["specific actionable tip 1", "tip 2"],
      "modelAnswer": "a perfect original exam-style practice response"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weakAreas: { type: Type.ARRAY, items: { type: Type.STRING } },
            suggestions: { type: Type.ARRAY, items: { type: Type.STRING } },
            modelAnswer: { type: Type.STRING }
          },
          required: ["score", "feedback", "strengths", "weakAreas", "suggestions", "modelAnswer"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Analysis Error:", error);
    return null;
  }
};

export const getSmartStudyPlan = async (profile: any) => {
  const model = 'gemini-3-flash-preview';
  const prompt = `Create a daily study plan for a Nigerian student. 
  Exams: ${profile.exams.join(', ')}. 
  Subjects: ${Object.values(profile.selectedSubjects).flat().join(', ')}.
  Weak subjects: ${profile.weakSubjects.join(', ')}.
  Suggest topics from the official ${profile.exams[0]} syllabus.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              time: { type: Type.STRING },
              subject: { type: Type.STRING },
              task: { type: Type.STRING }
            },
            propertyOrdering: ["time", "subject", "task"],
          }
        }
      }
    });
    return JSON.parse(response.text || '[]');
  } catch (error) {
    return [];
  }
};

