const SYLLABUS_INTEGRITY_PROMPT = `
You are an educational content generator for Nigerian secondary school examinations (WAEC, NECO, JAMB).
You must generate ONLY original exam-style practice questions.

STRICT RULES:
- NEVER copy, recall, paraphrase, or imitate any real past question.
- NEVER reference exam years (e.g., 'JAMB 2015'), paper codes, or leaked materials.
- NEVER claim questions are “official” past questions.
- All questions must be syllabus-aligned, original, and newly constructed by you.
- Label all practice outputs clearly as “exam-style practice questions”.

Target Exam Context:
If WAEC or NECO:
- Focus on understanding, explanation, structure, and marking points.
- Support theory, essay, and objective formats.
- Maintain a formal, examiner-standard tone.

If JAMB:
- Focus on CBT format.
- Emphasize speed, clarity, common traps, and option elimination.
- Keep explanations brief and time-aware.
`;

export const getTutorResponse = async (
  message: string, 
  examType: ExamType, 
  subject: string,
  chatHistory: { role: 'user' | 'assistant', content: string }[],
  image?: { data: string; mimeType: string }
) => {
  const model = 'gemini-3-pro-preview';

  const safetyLayer = "You are DEMO – Digital Exam Mentor. Respect exam integrity. NEVER provide answers to live ongoing exams.";
  const examLayer = `Current target exam: ${examType}. ${SYLLABUS_INTEGRITY_PROMPT}`;

  const baseSubject = subject.includes('Government') ? 'Government' : subject;
  const subjectPromptObj = SUBJECT_PROMPTS[baseSubject] || SUBJECT_PROMPTS['Mathematics']; 
  const subjectLayer = examType === 'JAMB' ? subjectPromptObj.JAMB : subjectPromptObj.WAEC;

  const systemInstruction = `${safetyLayer}\n\n${examLayer}\n\n${subjectLayer}${image ? '\n\nAn image of academic content (textbook, diagram, or handwriting) is provided. Analyze it carefully to help the student.' : ''}`;

  const parts: any[] = [];
  if (image) {
    parts.push({
      inlineData: {
        data: image.data,
        mimeType: image.mimeType
      }
    });
  }
  parts.push({ text: message });

  const contents = [
    ...chatHistory.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content }]
    })),
    { role: 'user', parts }
  ];

  try {
    const response = await ai.models.generateContent({
      model,
      contents: contents as any,
      config: {
        systemInstruction,
        temperature: 0.5,
      }
    });
    return response.text || "I'm sorry, I couldn't generate a response.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "An error occurred. Please check your internet connection.";
  }
};

export const generatePracticeQuestions = async (
  count: number,
  examType: ExamType,
  subject: string,
  type: 'OBJ' | 'THEORY' = 'OBJ'
): Promise<Question[]> => {
  const model = 'gemini-3-pro-preview';

  const prompt = `
    Generate ${count} original ${examType}-style ${type === 'OBJ' ? 'objective' : 'theory'} questions for the subject: ${subject}.

    Each question must:
    - Test understanding, not memorization.
    ${type === 'OBJ' ? '- Have 4 options (A–D).' : '- Be a structured theory/essay question.'}
    - Include one clearly correct answer or model marking point.
    ${type === 'OBJ' ? '- Include plausible distractors.' : '- Include a detailed marking scheme breakdown.'}
    - Provide a short examiner-style explanation (max 3 lines).

    IMPORTANT: Do not use any real past questions. Create fresh, original content aligned with the current Nigerian syllabus.

    Return the result as a JSON array of objects following this structure:
    {
      "questions": [
        {
          "id": "gen_string",
          "subjectId": "${subject}",
          "examType": "${examType}",
          "year": 2025,
          "text": "The question text",
          "options": ["Option A", "Option B", "Option C", "Option D"], // Only for OBJ
          "correctAnswer": "The correct option or full answer text",
          "explanation": "Examiner explanation",
          "type": "${type}"
        }
      ]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYLLABUS_INTEGRITY_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  subjectId: { type: Type.STRING },
                  examType: { type: Type.STRING },
                  year: { type: Type.NUMBER },
                  text: { type: Type.STRING },
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  correctAnswer: { type: Type.STRING },
                  explanation: { type: Type.STRING },
                  type: { type: Type.STRING }
                },
                required: ["id", "subjectId", "examType", "year", "text", "correctAnswer", "explanation", "type"]
              }
            }
          }
        }
      }
    });

    const parsed = JSON.parse(response.text || '{"questions": []}');
    return (parsed.questions || []).map((q: any) => ({
      ...q,
      examType: q.examType as ExamType,
      type: q.type as 'OBJ' | 'THEORY'
    }));
  } catch (error) {
    console.error("Question Generation Error:", error);
    return [];
  }
};

