import React, { useState, useEffect } from 'react';
import { UserProfile, Question } from '../types';
import { MOCK_QUESTIONS } from '../constants';
import { generatePracticeQuestions } from '../services/geminiService';
import { ChevronLeft, ChevronRight, Timer, Flag, CheckCircle, Info, Sparkles, Zap, ShieldAlert, Loader2 } from 'lucide-react';

interface Props {
  onBack: () => void;
  profile: UserProfile;
}

const CBTPractice: React.FC<Props> = ({ onBack, profile }) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [timeLeft, setTimeLeft] = useState(1200); 
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [isFinished, setIsFinished] = useState(false);
  const [isGenerating, setIsGenerating] = useState(true);

  useEffect(() => {
    const fetchQuestions = async () => {
      setIsGenerating(true);
      // Try to generate dynamic questions first, fallback to mock
      const generated = await generatePracticeQuestions(10, 'JAMB', profile.selectedSubjects.JAMB[0] || 'Mathematics');
      if (generated && generated.length > 0) {
        setQuestions(generated);
      } else {
        setQuestions(MOCK_QUESTIONS.filter(q => q.examType === 'JAMB'));
      }
      setIsGenerating(false);
    };
    fetchQuestions();
  }, [profile]);

  useEffect(() => {
    if (timeLeft > 0 && !isFinished && !isGenerating) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    } else if (timeLeft === 0) {
      setIsFinished(true);
    }
  }, [timeLeft, isFinished, isGenerating]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleFinish = () => {
    if (confirm("Are you sure you want to submit your CBT mock?")) {
      setIsFinished(true);
    }
  };

  const currentQ = questions[currentIdx];

  if (isGenerating) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-white p-6 text-center space-y-6 animate-pulse">
        <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-3xl flex items-center justify-center shadow-lg">
          <Loader2 className="w-10 h-10 animate-spin" />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-black text-slate-900">Setting up CBT...</h2>
          <p className="text-slate-500 font-medium">Drafting original exam-style practice questions based on the current JAMB syllabus.</p>
        </div>
        <div className="w-full max-w-xs h-2 bg-slate-100 rounded-full overflow-hidden">
          <div className="h-full bg-emerald-500 w-2/3 animate-progress"></div>
        </div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Powered by Gemini 3 Pro</p>
      </div>
    );
  }

  if (isFinished) {
    const score = questions.reduce((acc, q) => acc + (answers[q.id] === q.correctAnswer ? 1 : 0), 0);
    const timeSpent = 1200 - timeLeft;
    const avgSpeed = Math.round(timeSpent / questions.length);

    return (
      <div className="p-6 space-y-8 text-center animate-in zoom-in-95 duration-500 max-w-md mx-auto">
        <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto shadow-inner">
          <CheckCircle className="w-10 h-10" />
        </div>
        <div>
          <h2 className="text-3xl font-black text-slate-900">Exam Analysis</h2>
          <p className="text-slate-500 font-bold uppercase tracking-tighter mt-1">AI-Generated Mock Performance</p>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="p-5 rounded-[24px] bg-white border border-slate-100 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Raw Score</p>
            <p className="text-2xl font-black text-slate-900">{score} / {questions.length}</p>
          </div>
          <div className="p-5 rounded-[24px] bg-white border border-slate-100 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Avg. Speed</p>
            <p className="text-2xl font-black text-blue-600">{avgSpeed}s / q</p>
          </div>
        </div>

        <div className="bg-amber-50 p-5 rounded-[24px] border border-amber-100 flex items-start gap-4 text-left">
          <div className="w-10 h-10 bg-amber-100 text-amber-600 rounded-xl flex items-center justify-center shrink-0">
            <Zap className="w-5 h-5" />
          </div>
          <div>
            <p className="font-black text-amber-900 text-sm uppercase tracking-tighter mb-1">Trap Awareness Alert</p>
            <p className="text-xs text-amber-800 font-medium leading-relaxed">
              {avgSpeed < 10 ? "You're answering too quickly! JAMB distractors often look correct at first glance. Be careful." : "Great pace. You are within the ideal range for CBT accuracy."}
            </p>
          </div>
        </div>

        <div className="space-y-4">
          <h3 className="font-black text-slate-900 text-left px-1 uppercase text-xs tracking-widest">Corrections & Mastery</h3>
          {questions.map((q, i) => (
            <div key={q.id} className="text-left p-5 rounded-[28px] border border-slate-100 bg-white space-y-4 shadow-sm">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Question {i + 1}</span>
                <span className={`text-[10px] font-black px-3 py-1 rounded-full ${answers[q.id] === q.correctAnswer ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                  {answers[q.id] === q.correctAnswer ? 'CORRECT' : 'INCORRECT'}
