      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-white max-w-md mx-auto relative overflow-hidden">
      {/* CBT Header */}
      <div className="bg-emerald-600 p-4 pt-6 text-white flex items-center justify-between shadow-lg z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center font-black">J</div>
          <div>
            <h2 className="font-black text-sm uppercase tracking-tighter">JAMB AI Mock</h2>
            <p className="text-[10px] text-emerald-100 font-bold uppercase tracking-widest">Dynamic Practice Mode</p>
          </div>
        </div>
        <div className="flex items-center gap-2 bg-white/20 px-4 py-2 rounded-xl border border-white/30 backdrop-blur-sm">
          <Timer className="w-4 h-4" />
          <span className="font-mono font-black text-lg">{formatTime(timeLeft)}</span>
        </div>
      </div>

      {/* Question Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-8 z-0">
        <div className="flex items-center justify-between">
          <span className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm">
            Question {currentIdx + 1} of {questions.length}
          </span>
          <button className="text-slate-300 hover:text-red-500 transition-all active:scale-90">
            <Flag className="w-5 h-5" />
