                ? 'border-emerald-500 bg-emerald-50 shadow-md shadow-emerald-50' 
                : 'border-slate-100 bg-slate-50 hover:border-slate-300'
              }`}
            >
              <div className={`w-10 h-10 rounded-xl border-2 flex items-center justify-center font-black text-sm shrink-0 transition-all ${
