              </span>
            </button>
          ))}
        </div>
      </div>

      {/* CBT Footer Nav */}
      <div className="p-4 bg-white border-t border-slate-100 grid grid-cols-2 gap-4 pb-8 shadow-[0_-4px_20px_rgba(0,0,0,0.03)]">
        <button 
          disabled={currentIdx === 0}
          onClick={() => setCurrentIdx(currentIdx - 1)}
