        >
          <ChevronLeft className="w-5 h-5" /> BACK
        </button>
        {currentIdx === questions.length - 1 ? (
          <button 
            onClick={handleFinish}
            className="py-5 bg-emerald-600 text-white rounded-2xl font-black flex items-center justify-center gap-2 shadow-xl shadow-emerald-100 hover:bg-emerald-700 active:scale-95 transition-all"
