  examType: ExamType,
  subject: string,
  type: 'OBJ' | 'THEORY' = 'OBJ'
): Promise<Question[]> => {
  const model = 'gemini-3-pro-preview';

  let typeSpecificPrompt = '';
  if (type === 'OBJ') {
    typeSpecificPrompt = `
      Each question must:
      - Test understanding, not memorization.
      - Have 4 options (A–D).
      - Include one clearly correct answer.
      - Include plausible distractors.
      - Provide a short examiner-style explanation (max 3 lines).
    `;
  } else {
    typeSpecificPrompt = `
      Each question must:
      - Be an original ${examType}-style theory or essay question.
      - Test deep understanding and syllabus-aligned concepts.
      - Avoid vague wording.
      - Provide a comprehensive marking guide.

      The marking guide must include:
      - Introduction points: What the student should define or state initially.
      - Main content points: Key facts, arguments, or steps required for full marks.
      - Conclusion expectations: How the student should wrap up or summarize.
    `;
  }

  const prompt = `
    Generate ${count} original ${examType}-style ${type === 'OBJ' ? 'objective' : 'theory'} questions for the subject: ${subject}.

    ${typeSpecificPrompt}

    IMPORTANT: Do not use any real past questions. Create fresh, original content aligned with the current Nigerian syllabus.

    Return the result as a JSON array of objects following this structure:
    {
      "questions": [
        {
          "id": "gen_" + unique string,
          "subjectId": "${subject}",
          "examType": "${examType}",
          "year": 2025,
          "text": "The question text",
          "options": ["Option A", "Option B", "Option C", "Option D"], // ONLY for OBJ questions
          "correctAnswer": "The full correct answer (for OBJ, the option text. For THEORY, a model sample answer)",
          "explanation": "Examiner explanation. For THEORY, format this as a detailed Marking Scheme with sections: [Introduction], [Main Content], [Conclusion]",
          "type": "${type}"
        }
      ]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        systemInstruction: SYLLABUS_INTEGRITY_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  subjectId: { type: Type.STRING },
                  examType: { type: Type.STRING },
                  year: { type: Type.NUMBER },
                  text: { type: Type.STRING },
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  correctAnswer: { type: Type.STRING },
                  explanation: { type: Type.STRING },
                  type: { type: Type.STRING }
                },
                required: ["id", "subjectId", "examType", "year", "text", "correctAnswer", "explanation", "type"]
              }
            }
          }
        }
      }
    });

    const parsed = JSON.parse(response.text || '{"questions": []}');
    return (parsed.questions || []).map((q: any) => ({
      ...q,
      examType: q.examType as ExamType,
      type: q.type as 'OBJ' | 'THEORY'
    }));
  } catch (error) {
    console.error("Question Generation Error:", error);
    return [];
  }
};

