    const examType = profile.exams.find(e => e === 'WAEC' || e === 'NECO') || 'WAEC';
    const questions = await generatePracticeQuestions(1, examType, activeSubject, 'THEORY');
    if (questions && questions.length > 0) {
      setQuestion(questions[0].text);
      setMarkingScheme(questions[0].explanation);
