const SYLLABUS_INTEGRITY_PROMPT = `
You are an educational content generator for Nigerian secondary school examinations (WAEC, NECO, JAMB).
You must generate ONLY original exam-style practice questions.

STRICT RULES:
- NEVER copy, recall, paraphrase, or imitate any real past question.
- NEVER reference exam years (e.g., 'JAMB 2015'), paper codes, or leaked materials.
- NEVER claim questions are “official” past questions.
- All questions must be syllabus-aligned, original, and newly constructed by you.
- Label all practice outputs clearly as “exam-style practice questions”.

Target Exam Context:
If WAEC or NECO:
- Focus on understanding, explanation, structure, and marking points.
- Support theory, essay, and objective formats.
- Maintain a formal, examiner-standard tone.

If JAMB:
- Focus on CBT format.
- Emphasize speed, clarity, common traps, and option elimination.
- Keep explanations brief and time-aware.
`;

export const getTutorResponse = async (
  message: string, 
  examType: ExamType, 
  subject: string,
  chatHistory: { role: 'user' | 'assistant', content: string }[],
  image?: { data: string; mimeType: string }
) => {
  const model = 'gemini-3-pro-preview';

  const safetyLayer = "You are DEMO – Digital Exam Mentor. Respect exam integrity. NEVER provide answers to live ongoing exams.";
  const examLayer = `Current target exam: ${examType}. ${SYLLABUS_INTEGRITY_PROMPT}`;

  const baseSubject = subject.includes('Government') ? 'Government' : subject;
  const subjectPromptObj = SUBJECT_PROMPTS[baseSubject] || SUBJECT_PROMPTS['Mathematics']; 
  const subjectLayer = examType === 'JAMB' ? subjectPromptObj.JAMB : subjectPromptObj.WAEC;

  const systemInstruction = `${safetyLayer}\n\n${examLayer}\n\n${subjectLayer}${image ? '\n\nAn image of academic content (textbook, diagram, or handwriting) is provided. Analyze it carefully to help the student.' : ''}`;

  const parts: any[] = [];
  if (image) {
    parts.push({
      inlineData: {
        data: image.data,
        mimeType: image.mimeType
      }
    });
  }
  parts.push({ text: message });

  const contents = [
    ...chatHistory.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content }]
    })),
    { role: 'user', parts }
  ];

  try {
    const response = await ai.models.generateContent({
      model,
      contents: contents as any,
      config: {
        systemInstruction,
        temperature: 0.5,
      }
    });
    return response.text || "I'm sorry, I couldn't generate a response.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "An error occurred. Please check your internet connection.";
  }
};

