      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weakAreas: { type: Type.ARRAY, items: { type: Type.STRING } },
            suggestions: { type: Type.ARRAY, items: { type: Type.STRING } },
            modelAnswer: { type: Type.STRING }
          },
          required: ["score", "feedback", "strengths", "weakAreas", "suggestions", "modelAnswer"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Analysis Error:", error);
    return null;
  }
};

export const getSmartStudyPlan = async (profile: any) => {
  const model = 'gemini-3-flash-preview';
  const prompt = `Create a daily study plan for a Nigerian student. 
  Exams: ${profile.exams.join(', ')}. 
  Subjects: ${Object.values(profile.selectedSubjects).flat().join(', ')}.
  Weak subjects: ${profile.weakSubjects.join(', ')}.
  Suggest topics from the official ${profile.exams[0]} syllabus.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              time: { type: Type.STRING },
              subject: { type: Type.STRING },
              task: { type: Type.STRING }
            },
            propertyOrdering: ["time", "subject", "task"],
          }
        }
      }
    });
    return JSON.parse(response.text || '[]');
  } catch (error) {
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { UserProfile, Question } from '../types';
import { MOCK_QUESTIONS } from '../constants';
import { generatePracticeQuestions } from '../services/geminiService';
import { ChevronLeft, ChevronRight, Timer, Flag, CheckCircle, Info, Sparkles, Zap, Loader2, Target, Clock, Trophy } from 'lucide-react';

interface Props {
  onBack: () => void;
  profile: UserProfile;
}

type SessionMode = 'DRILL' | 'FOCUS' | 'FULL';

const CBTPractice: React.FC<Props> = ({ onBack, profile }) => {
  const [mode, setMode] = useState<SessionMode | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [timeLeft, setTimeLeft] = useState(0); 
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [isFinished, setIsFinished] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  const startSession = async (selectedMode: SessionMode) => {
    setMode(selectedMode);
    setIsGenerating(true);

    const subject = profile.selectedSubjects.JAMB[0] || 'Mathematics';
    const isEnglish = subject.toLowerCase().includes('english');

    let count = 10;
    let time = 600; // 10 mins

    if (selectedMode === 'DRILL') {
      count = 10;
      time = 600;
    } else if (selectedMode === 'FOCUS') {
      count = 20;
      time = 1500; // 25 mins
    } else if (selectedMode === 'FULL') {
      count = isEnglish ? 60 : 40;
      time = isEnglish ? 3600 : 2700; // 60 or 45 mins
    }

    setTimeLeft(time);

    try {
      const generated = await generatePracticeQuestions(count, 'JAMB', subject);
      if (generated && generated.length > 0) {
        setQuestions(generated);
      } else {
        setQuestions(MOCK_QUESTIONS.filter(q => q.examType === 'JAMB').slice(0, count));
      }
    } catch (error) {
      console.error(error);
      setQuestions(MOCK_QUESTIONS.filter(q => q.examType === 'JAMB').slice(0, count));
    }

    setIsGenerating(false);
  };

  useEffect(() => {
    if (mode && timeLeft > 0 && !isFinished && !isGenerating) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    } else if (mode && timeLeft === 0 && !isGenerating && !isFinished) {
      setIsFinished(true);
    }
  }, [timeLeft, isFinished, isGenerating, mode]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleFinish = () => {
    if (confirm("Are you sure you want to submit your CBT mock?")) {
      setIsFinished(true);
    }
  };

  if (!mode) {
    return (
      <div className="p-6 space-y-8 animate-in fade-in duration-500 max-w-md mx-auto h-full flex flex-col justify-center">
        <div className="text-center space-y-2 mb-4">
           <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-3xl flex items-center justify-center mx-auto mb-4">
              <Zap className="w-8 h-8" />
           </div>
           <h2 className="text-3xl font-black text-slate-900">Choose Session</h2>
           <p className="text-slate-500 font-medium">Original JAMB questions based on the current syllabus.</p>
        </div>

        <div className="space-y-4">
          <SessionOption 
            icon={<Clock className="text-blue-500" />} 
            title="Quick Drill" 
            desc="10 Questions • 10 Minutes" 
            onClick={() => startSession('DRILL')}
          />
          <SessionOption 
            icon={<Target className="text-emerald-500" />} 
            title="Focus Practice" 
            desc="20 Questions • 25 Minutes" 
            onClick={() => startSession('FOCUS')}
          />
          <SessionOption 
            icon={<Trophy className="text-amber-500" />} 
            title="Full AI Mock" 
            desc={`${profile.selectedSubjects.JAMB[0]?.includes('English') ? '60' : '40'} Questions • Real Exam Timing`} 
            onClick={() => startSession('FULL')}
          />
        </div>

        <button onClick={onBack} className="w-full py-4 text-slate-400 font-black text-sm uppercase tracking-widest hover:text-slate-600 transition-colors">
          Cancel & Exit
        </button>
      </div>
    );
  }

  if (isGenerating) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-white p-6 text-center space-y-6 animate-pulse">
        <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-3xl flex items-center justify-center shadow-lg">
          <Loader2 className="w-10 h-10 animate-spin" />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-black text-slate-900">Drafting Questions...</h2>
          <p className="text-slate-500 font-medium">Generating {mode === 'FULL' ? 'a full length' : 'a practice'} mock for {profile.selectedSubjects.JAMB[0] || 'your subject'}.</p>
        </div>
        <div className="w-full max-w-xs h-2 bg-slate-100 rounded-full overflow-hidden">
          <div className="h-full bg-emerald-500 w-2/3 animate-progress"></div>
        </div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Powered by Gemini 3 Pro</p>
      </div>
    );
  }

  if (isFinished) {
    const score = questions.reduce((acc, q) => acc + (answers[q.id] === q.correctAnswer ? 1 : 0), 0);
    const timeSpent = (mode === 'DRILL' ? 600 : mode === 'FOCUS' ? 1500 : 3600) - timeLeft;
    const avgSpeed = questions.length > 0 ? Math.round(timeSpent / questions.length) : 0;

    return (
      <div className="p-6 space-y-8 text-center animate-in zoom-in-95 duration-500 max-w-md mx-auto">
        <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto shadow-inner">
          <CheckCircle className="w-10 h-10" />
        </div>
        <div>
          <h2 className="text-3xl font-black text-slate-900">Mock Complete</h2>
          <p className="text-slate-500 font-bold uppercase tracking-tighter mt-1">{mode === 'FULL' ? 'Full Session' : 'Practice'} Analysis</p>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="p-5 rounded-[24px] bg-white border border-slate-100 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Score</p>
            <p className="text-2xl font-black text-slate-900">{score} / {questions.length}</p>
          </div>
          <div className="p-5 rounded-[24px] bg-white border border-slate-100 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Pace</p>
            <p className="text-2xl font-black text-blue-600">{avgSpeed}s / q</p>
          </div>
        </div>

        <div className="bg-amber-50 p-5 rounded-[24px] border border-amber-100 flex items-start gap-4 text-left">
          <div className="w-10 h-10 bg-amber-100 text-amber-600 rounded-xl flex items-center justify-center shrink-0">
            <Zap className="w-5 h-5" />
          </div>
          <div>
            <p className="font-black text-amber-900 text-sm uppercase tracking-tighter mb-1">AI Recommendation</p>
            <p className="text-xs text-amber-800 font-medium leading-relaxed">
              {score / questions.length > 0.7 ? "Excellent performance! Maintain this pace." : "You need to focus on accuracy. Try reviewing the explanations below carefully."}
            </p>
          </div>
        </div>

        <div className="space-y-4">
          <h3 className="font-black text-slate-900 text-left px-1 uppercase text-xs tracking-widest">Review Corrections</h3>
          {questions.map((q, i) => (
            <div key={q.id} className="text-left p-5 rounded-[28px] border border-slate-100 bg-white space-y-4 shadow-sm">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Q{i + 1}</span>
                <span className={`text-[10px] font-black px-3 py-1 rounded-full ${answers[q.id] === q.correctAnswer ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                  {answers[q.id] === q.correctAnswer ? 'PASSED' : 'FAILED'}
                </span>
              </div>
              <p className="text-sm font-bold text-slate-800 leading-relaxed">{q.text}</p>

              <div className="p-4 rounded-2xl bg-blue-50/50 text-blue-900 text-xs space-y-3 border border-blue-100">
                <div className="flex gap-2 font-black text-blue-900 border-b border-blue-200/50 pb-2 mb-1">
                  <Sparkles className="w-4 h-4 text-blue-600" />
                  <span className="uppercase tracking-tighter">Examiner Logic</span>
                </div>
                <p className="leading-relaxed font-semibold">{q.explanation}</p>
              </div>
            </div>
          ))}
        </div>
        <button onClick={onBack} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg hover:bg-slate-800 transition-all shadow-xl shadow-slate-200">Back to Dashboard</button>
      </div>
    );
  }

  const currentQ = questions[currentIdx];

  return (
    <div className="flex flex-col h-screen bg-white max-w-md mx-auto relative overflow-hidden">
      {/* CBT Header */}
      <div className="bg-emerald-600 p-4 pt-6 text-white flex items-center justify-between shadow-lg z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center font-black">J</div>
          <div>
            <h2 className="font-black text-sm uppercase tracking-tighter">JAMB AI Mock</h2>
            <p className="text-[10px] text-emerald-100 font-bold uppercase tracking-widest">{mode === 'FULL' ? 'Full Exam' : 'Practice'}</p>
          </div>
        </div>
        <div className="flex items-center gap-2 bg-white/20 px-4 py-2 rounded-xl border border-white/30 backdrop-blur-sm">
          <Timer className="w-4 h-4" />
          <span className="font-mono font-black text-lg">{formatTime(timeLeft)}</span>
        </div>
      </div>

      {/* Question Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-8 z-0">
        <div className="flex items-center justify-between">
          <span className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm">
            Question {currentIdx + 1} of {questions.length}
          </span>
          <button className="text-slate-300 hover:text-red-500 transition-all active:scale-90">
            <Flag className="w-5 h-5" />
          </button>
        </div>

        <div className="space-y-4">
          <h3 className="text-xl font-bold text-slate-900 leading-relaxed">
            {currentQ?.text}
          </h3>
        </div>

        <div className="space-y-4 pt-4">
          {currentQ?.options?.map((opt, i) => (
            <button 
              key={i}
              onClick={() => setAnswers({...answers, [currentQ.id]: opt})}
              className={`w-full p-5 rounded-[24px] border-2 text-left transition-all flex items-center gap-5 group active:scale-[0.98] ${
                answers[currentQ.id] === opt 
                ? 'border-emerald-500 bg-emerald-50 shadow-md shadow-emerald-50' 
                : 'border-slate-100 bg-slate-50 hover:border-slate-300'
              }`}
            >
              <div className={`w-10 h-10 rounded-xl border-2 flex items-center justify-center font-black text-sm shrink-0 transition-all ${
                answers[currentQ.id] === opt 
                ? 'bg-emerald-500 text-white border-emerald-500 scale-110 shadow-lg' 
                : 'bg-white text-slate-400 border-slate-200 group-hover:border-slate-400'
              }`}>
                {String.fromCharCode(65 + i)}
              </div>
              <span className={`font-black text-sm ${answers[currentQ.id] === opt ? 'text-emerald-900' : 'text-slate-600'}`}>
                {opt}
              </span>
            </button>
          ))}
        </div>
      </div>

      {/* CBT Footer Nav */}
      <div className="p-4 bg-white border-t border-slate-100 grid grid-cols-2 gap-4 pb-8 shadow-[0_-4px_20px_rgba(0,0,0,0.03)]">
        <button 
          disabled={currentIdx === 0}
          onClick={() => setCurrentIdx(currentIdx - 1)}
          className="py-5 border-2 border-slate-100 rounded-2xl font-black text-slate-400 disabled:opacity-30 flex items-center justify-center gap-2 hover:bg-slate-50 transition-all"
        >
          <ChevronLeft className="w-5 h-5" /> BACK
        </button>
        {currentIdx === questions.length - 1 ? (
          <button 
            onClick={handleFinish}
            className="py-5 bg-emerald-600 text-white rounded-2xl font-black flex items-center justify-center gap-2 shadow-xl shadow-emerald-100 hover:bg-emerald-700 active:scale-95 transition-all"
          >
            SUBMIT <CheckCircle className="w-5 h-5" />
          </button>
        ) : (
          <button 
            onClick={() => setCurrentIdx(currentIdx + 1)}
            className="py-5 bg-slate-900 text-white rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-slate-800 active:scale-95 transition-all"
          >
            NEXT <ChevronRight className="w-5 h-5" />
          </button>
        )}
      </div>

      {/* Progress Bubbles */}
      <div className="px-4 py-3 bg-slate-50 flex gap-2 overflow-x-auto border-t border-slate-100 custom-scrollbar scroll-smooth">
        {questions.map((q, i) => (
          <button 
            key={q.id}
            onClick={() => setCurrentIdx(i)}
            className={`min-w-[44px] h-11 rounded-xl text-xs font-black border-2 transition-all flex-shrink-0 flex items-center justify-center ${
              currentIdx === i 
              ? 'bg-emerald-600 text-white border-emerald-600 shadow-md scale-110 z-10' 
              : answers[q.id] 
                ? 'bg-emerald-50 text-emerald-700 border-emerald-200' 
                : 'bg-white text-slate-300 border-slate-100'
            }`}
          >
            {i + 1}
          </button>
        ))}
      </div>
    </div>
  );
};

