          <button onClick={onBack} className="p-1 hover:bg-slate-100 rounded-lg">
            <ChevronLeft className="w-6 h-6" />
          </button>
          <div>
            <h2 className="text-xl font-bold text-slate-900 leading-none">Theory Coach</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">WAEC/NECO Standard Set</p>
          </div>
        </div>
        <select 
          value={activeSubject}
          onChange={(e) => setActiveSubject(e.target.value)}
          className="text-xs font-black text-blue-600 bg-blue-50 border-none rounded-lg px-2 py-1 outline-none"
        >
          {Array.from(new Set([...profile.selectedSubjects.WAEC, ...profile.selectedSubjects.NECO])).map(s => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
      </div>

      {/* Question Selector Tray */}
      {!isLoadingQuestions && questions.length > 1 && (
