              className={`px-4 py-1.5 rounded-full text-[10px] font-black transition-all ${
                currentIdx === i 
                ? 'bg-blue-600 text-white shadow-md' 
                : results[i] 
                  ? 'bg-emerald-50 text-emerald-600' 
                  : 'bg-slate-50 text-slate-400'
