              <Sparkles className="absolute top-2 right-2 w-12 h-12 text-white/10 group-hover:scale-110 transition-transform" />
              <div className="inline-flex items-center gap-2 bg-white/20 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest mb-3 border border-white/20">
