2. Body (Key facts/steps)
3. Conclusion (Summary)"
                className="w-full h-80 p-5 rounded-3xl border-2 border-slate-100 focus:border-blue-500 bg-white outline-none transition-all text-slate-800 leading-relaxed shadow-sm resize-none text-sm font-medium"
              />
            </div>

            <div className="flex gap-3">
              <button 
                onClick={() => setCurrentIdx((currentIdx + 1) % questions.length)}
                className="flex-1 bg-white border-2 border-slate-100 text-slate-600 py-4 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-slate-50 active:scale-95 transition-all"
              >
                Next Task
              </button>
              <button 
