import crypto from 'crypto';

/**
 * Paystack Webhook Handler
 * 
 * @param req The incoming HTTP request
 * @param res The outgoing HTTP response
 */
export const handlePaystackWebhook = async (req: any, res: any) => {
  const secret = process.env.PAYSTACK_SECRET_KEY || 'sk_test_xxx';

  // 1. Verify the signature
  const hash = crypto
    .createHmac('sha512', secret)
    .update(JSON.stringify(req.body))
    .digest('hex');

  if (hash !== req.headers['x-paystack-signature']) {
    return res.status(401).send('Invalid signature');
  }

  // 2. Retrieve the request's body
  const event = req.body;

  // 3. Handle specific event types
  switch (event.event) {
    case 'charge.success':
      const { email, amount, metadata } = event.data;
      console.log(`Payment successful for ${email}: ${amount / 100} NGN`);

      // LOGIC: Update your database here
      // await db.users.update({ email }, { isPaid: true });
      break;

    case 'transfer.success':
      // Handle other events if necessary
      break;

    default:
      console.log('Unhandled event type:', event.event);
  }

  // 4. Acknowledge receipt with 200 OK
  res.status(200).send('Webhook received');
};

