);

export default App;

import React, { useState } from 'react';
import { UserProfile, ExamType } from '../types';
import { SUBJECTS_LIST, EXAM_METADATA } from '../constants';
import { ArrowRight, ChevronLeft, Calendar } from 'lucide-react';

interface Props {
  onComplete: (profile: UserProfile) => void;
}

const Onboarding: React.FC<Props> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<Partial<UserProfile>>({
    name: '',
    email: '',
    exams: [],
    selectedSubjects: { WAEC: [], NECO: [], JAMB: [] },
    examDates: { WAEC: '', NECO: '', JAMB: '' },
    weakSubjects: []
  });

  const updateExams = (exam: ExamType) => {
    const current = formData.exams || [];
    if (current.includes(exam)) {
      setFormData({ ...formData, exams: current.filter(e => e !== exam) });
    } else {
      setFormData({ ...formData, exams: [...current, exam] });
    }
  };

  const updateSubjects = (exam: ExamType, subject: string) => {
    const subs = { ...formData.selectedSubjects } as Record<ExamType, string[]>;
    if (subs[exam].includes(subject) ) {
      subs[exam] = subs[exam].filter(s => s !== subject);
    } else {
      subs[exam] = [...subs[exam], subject];
    }
    setFormData({ ...formData, selectedSubjects: subs });
  };

  const updateDate = (exam: ExamType, date: string) => {
    const dates = { ...formData.examDates } as Record<ExamType, string>;
    dates[exam] = date;
    setFormData({ ...formData, examDates: dates });
  };

  const handleNext = () => setStep(step + 1);
  const handleBack = () => setStep(step - 1);

  const areDatesSet = () => {
    if (!formData.exams) return false;
    return formData.exams.every(exam => !!formData.examDates?.[exam]);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 max-w-md mx-auto">
      {step > 1 && (
        <button onClick={handleBack} className="mb-8 p-2 -ml-2 hover:bg-slate-100 rounded-full w-fit">
          <ChevronLeft className="w-6 h-6 text-slate-600" />
        </button>
      )}

      {step === 1 && (
        <div className="flex-1 flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="mb-10 text-center">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl font-bold mx-auto mb-4">D</div>
            <h1 className="text-3xl font-bold text-slate-900 mb-2">Welcome to DEMO</h1>
            <p className="text-slate-500 font-medium">Digital Exam mentor</p>
            <p className="text-slate-400 text-sm mt-2">Your AI-powered guide to smashing WAEC, NECO & JAMB exams.</p>
          </div>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">Full Name</label>
              <input 
                type="text" 
                className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-blue-500 outline-none transition-all"
                placeholder="Abiola Johnson"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">Email / Phone</label>
              <input 
                type="text" 
                className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-blue-500 outline-none transition-all"
                placeholder="example@mail.com"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          </div>
          <button 
            disabled={!formData.name || !formData.email}
            onClick={handleNext}
            className="mt-auto w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-2 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            Get Started <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      )}

      {step === 2 && (
        <div className="flex-1 flex flex-col animate-in fade-in slide-in-from-right-4 duration-500">
          <h2 className="text-2xl font-bold text-slate-900 mb-2">What are you writing?</h2>
          <p className="text-slate-500 mb-8">You can select multiple exams if you're taking more than one.</p>

          <div className="space-y-4">
            {(['WAEC', 'NECO', 'JAMB'] as ExamType[]).map(exam => (
              <button 
                key={exam}
                onClick={() => updateExams(exam)}
                className={`w-full p-6 rounded-2xl border-2 text-left transition-all ${
                  formData.exams?.includes(exam) 
                    ? 'border-blue-600 bg-blue-50' 
                    : 'border-slate-100 bg-white hover:border-slate-200'
                }`}
              >
                <h3 className="text-xl font-bold text-slate-900">{exam}</h3>
                <p className="text-slate-500 text-sm">{EXAM_METADATA[exam].fullName}</p>
              </button>
            ))}
          </div>

          <button 
            disabled={!formData.exams?.length}
            onClick={handleNext}
            className="mt-auto w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-blue-700 disabled:opacity-50 transition-all"
          >
            Continue
          </button>
        </div>
      )}

      {step === 3 && (
        <div className="flex-1 flex flex-col animate-in fade-in slide-in-from-right-4 duration-500">
          <h2 className="text-2xl font-bold text-slate-900 mb-2">Select Your Subjects</h2>
          <p className="text-slate-500 mb-6">Pick the subjects you'll be writing in your selected exams.</p>

          <div className="flex-1 overflow-y-auto space-y-6 pr-1 custom-scrollbar">
            {formData.exams?.map(exam => (
              <div key={exam}>
                <h3 className="font-bold text-blue-600 mb-3 flex items-center gap-2">
                  <span className="w-1.5 h-6 bg-blue-600 rounded-full"></span>
                  {exam} Subjects
                </h3>
                <div className="grid grid-cols-2 gap-2">
                  {SUBJECTS_LIST.map(subject => (
                    <button 
                      key={subject}
                      onClick={() => updateSubjects(exam, subject)}
                      className={`p-3 text-xs font-semibold rounded-xl border transition-all text-center ${
                        formData.selectedSubjects?.[exam].includes(subject)
                          ? 'bg-blue-600 text-white border-blue-600 shadow-md'
                          : 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100'
                      }`}
                    >
                      {subject}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>

          <button 
            disabled={!formData.exams?.every(e => formData.selectedSubjects?.[e].length > 0)}
            onClick={handleNext}
            className="mt-8 w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-blue-700 disabled:opacity-50 transition-all"
          >
            Set Exam Dates
          </button>
        </div>
      )}

      {step === 4 && (
        <div className="flex-1 flex flex-col animate-in fade-in slide-in-from-right-4 duration-500">
          <h2 className="text-2xl font-bold text-slate-900 mb-2">When are your exams?</h2>
          <p className="text-slate-500 mb-8">We'll use this to build your personalized countdown and study timeline.</p>

          <div className="space-y-6">
            {formData.exams?.map(exam => (
              <div key={exam} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                <div className="flex items-center gap-3 text-slate-900">
                  <Calendar className="text-blue-600 w-5 h-5" />
                  <h3 className="font-bold text-lg">{exam} Start Date</h3>
                </div>
                <input 
                  type="date"
                  min={new Date().toISOString().split('T')[0]}
                  value={formData.examDates?.[exam] || ''}
                  onChange={(e) => updateDate(exam, e.target.value)}
                  className="w-full p-4 rounded-xl border-2 border-slate-200 focus:border-blue-500 outline-none font-bold text-slate-700 bg-white"
                />
              </div>
            ))}
          </div>

          <button 
            disabled={!areDatesSet()}
            onClick={() => onComplete(formData as UserProfile)}
            className="mt-auto w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-blue-700 disabled:opacity-50 transition-all"
          >
            Complete Setup
          </button>
        </div>
      )}
    </div>
  );
};

export default Onboarding;

import React from 'react';
import { UserProfile, ExamType } from '../types';
import { MOCK_STUDY_PLAN } from '../constants';
import { Calendar, Clock, Target, ArrowRight, Play, Book, BrainCircuit, MessageCircleQuestion, ChevronLeft, Camera } from 'lucide-react';

interface Props {
  profile: UserProfile;
  onNavigate: (tab: string) => void;
  onStartEssay: () => void;
  onStartCBT: () => void;
  onShowContact: () => void;
}

const Dashboard: React.FC<Props> = ({ profile, onNavigate, onStartEssay, onStartCBT, onShowContact }) => {

  const calculateDaysLeft = (dateString: string) => {
    if (!dateString) return null;
    const examDate = new Date(dateString);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    examDate.setHours(0, 0, 0, 0);

    const diffTime = examDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  };

  const getProgressPercentage = (daysLeft: number) => {
    // Assume a 100-day preparation window for the progress bar
    const totalWindow = 100;
    const consumed = totalWindow - Math.min(daysLeft, totalWindow);
    return Math.max(0, Math.min(100, (consumed / totalWindow) * 100));
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <section className="space-y-1 relative">
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-black text-slate-900">Hi, {profile.name.split(' ')[0]} 👋</h2>
        </div>
        <p className="text-slate-500 font-medium">You have {profile.exams.join(' & ')} exams coming up.</p>
      </section>

      {/* Quick Actions */}
      <section className="grid grid-cols-2 gap-3">
        <button 
          onClick={() => onNavigate('tutor')}
          className="bg-blue-600 text-white p-4 rounded-[28px] flex flex-col gap-3 hover:bg-blue-700 transition-all hover:scale-[1.02] active:scale-95 shadow-lg shadow-blue-100"
        >
          <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center">
            <BrainCircuit className="w-6 h-6" />
          </div>
          <div className="text-left">
            <p className="font-black text-sm uppercase tracking-tighter">AI Tutor</p>
            <p className="text-[10px] text-blue-100 font-medium">Ask & Learn 24/7</p>
          </div>
        </button>
        <button 
          onClick={() => onNavigate('tutor')}
