  data: string;
  mimeType: string;
  preview: string;
}

const ResponseRenderer: React.FC<{ content: string }> = ({ content }) => {
  // Simple parser to identify headers or key concepts and style them differently
  const lines = content.split('\n');

  return (
    <div className="space-y-3">
      {lines.map((line, i) => {
        if (line.startsWith('###') || line.startsWith('**')) {
          return <h4 key={i} className="font-black text-emerald-900 text-sm uppercase tracking-tight mt-4 border-l-4 border-emerald-500 pl-2">{line.replace(/[#*]/g, '').trim()}</h4>;
        }
        if (line.startsWith('-') || line.match(/^\d\./)) {
          return (
            <div key={i} className="flex gap-2 items-start pl-2">
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-400 mt-2 shrink-0"></div>
              <p className="text-slate-700 leading-relaxed">{line.replace(/^[- \d.]*/, '').trim()}</p>
            </div>
          );
        }
        if (line.includes('[Key Concept]') || line.includes('[Tip]')) {
          return (
            <div key={i} className="bg-emerald-50 border border-emerald-100 p-4 rounded-2xl my-4 shadow-sm">
              <div className="flex items-center gap-2 mb-1">
                <Lightbulb size={14} className="text-emerald-600" />
                <span className="text-[10px] font-black text-emerald-700 uppercase tracking-widest">Crucial Tip</span>
              </div>
              <p className="text-xs font-bold text-emerald-900 leading-relaxed">{line.replace(/\[.*?\]/, '').trim()}</p>
            </div>
          );
        }
        return <p key={i} className="leading-relaxed text-slate-700">{line}</p>;
      })}
    </div>
  );
};

const AITutor: React.FC<Props> = ({ profile }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'assistant', 
      content: `Hello ${profile.name.split(' ')[0]}! I'm your DEMO AI Mentor. I can help you with ${profile.selectedSubjects[profile.exams[0]].join(', ')} for your ${profile.exams[0]} prep. 

Ask me anything or upload a photo of a diagram or question you're stuck on!`, 
      timestamp: Date.now() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [activeMode, setActiveMode] = useState<ExamType>(profile.exams[0]);
  const [activeSubject, setActiveSubject] = useState<string>(profile.selectedSubjects[profile.exams[0]][0] || 'Mathematics');
  const [showSubjectMenu, setShowSubjectMenu] = useState(false);
  const [selectedImage, setSelectedImage] = useState<ImageState | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      alert('Please select an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      const base64 = (reader.result as string).split(',')[1];
      setSelectedImage({
        data: base64,
        mimeType: file.type,
        preview: reader.result as string
      });
    };
    reader.readAsDataURL(file);
  };

  const handleSend = async (customInput?: string) => {
    const msgText = customInput || input;
    if ((!msgText.trim() && !selectedImage) || isTyping) return;

    const currentImage = selectedImage;
    const currentInput = msgText;

    const userMessage: Message = { 
      role: 'user', 
      content: currentInput || "[Visual Content Analysis Requested]", 
      timestamp: Date.now() 
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setSelectedImage(null);
    setIsTyping(true);

    const history = messages.slice(-10).map(m => ({ role: m.role, content: m.content }));
    const response = await getTutorResponse(
      currentInput || "Analyze the academic content in this image.", 
      activeMode, 
      activeSubject, 
      history,
      currentImage ? { data: currentImage.data, mimeType: currentImage.mimeType } : undefined
    );

    setMessages(prev => [...prev, { 
      role: 'assistant', 
      content: response, 
      timestamp: Date.now() 
    }]);
    setIsTyping(false);
  };

  const handleModeChange = (mode: ExamType) => {
    setActiveMode(mode);
    const modeSubjects = profile.selectedSubjects[mode];
    if (modeSubjects && modeSubjects.length > 0) {
      setActiveSubject(modeSubjects[0]);
