        <div className="absolute bottom-40 right-10 -rotate-12"><BookOpen size={140} /></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2"><Sparkles size={300} /></div>
      </div>

      {/* Header */}
      <div className="bg-white/95 backdrop-blur-xl border-b border-slate-200/60 px-4 py-3 flex flex-col gap-2 z-30 sticky top-0 shadow-sm">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="relative">
              <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-emerald-500 to-emerald-700 flex items-center justify-center shadow-lg shadow-emerald-100">
                <Sparkles className="w-5 h-5 text-white" />
              </div>
              <div className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-emerald-400 border-2 border-white rounded-full"></div>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Target Exam</p>
              <div className="flex gap-1.5 mt-0.5">
                {profile.exams.map(exam => (
                  <button 
                    key={exam}
                    onClick={() => handleModeChange(exam)}
                    className={`px-2.5 py-1 text-[10px] font-black rounded-lg border transition-all ${
                      activeMode === exam 
