              <X size={10} />
            </button>
            <div className="absolute -bottom-2 -left-2 bg-emerald-600 text-white px-2 py-0.5 rounded-lg text-[7px] font-black uppercase tracking-widest">
              Visual Input
            </div>
          </div>
          <p className="text-[10px] font-bold text-slate-400 italic">Analyzing Academic Diagram...</p>
        </div>
      )}

      {/* Input area */}
      <div className="p-4 bg-white border-t border-slate-200/60 pb-8 z-20 shadow-[0_-4px_20px_rgba(0,0,0,0.03)]">
        <div className="max-w-xl mx-auto">
          <div className="flex items-end gap-2 bg-slate-50 rounded-3xl p-2 border border-slate-200/60 focus-within:border-emerald-500 focus-within:bg-white focus-within:ring-4 focus-within:ring-emerald-50 transition-all duration-300 group">
