import React, { useState, useEffect } from 'react';
import { UserProfile, Question } from '../types';
import { analyzeEssay, generatePracticeQuestions } from '../services/geminiService';
import { ChevronLeft, Send, Sparkles, CheckCircle2, AlertCircle, RefreshCw, Lightbulb, TrendingUp, BookOpen, Loader2, ListChecks, Award, Target, Info } from 'lucide-react';

interface Props {
  onBack: () => void;
  profile: UserProfile;
}

const EssayCoach: React.FC<Props> = ({ onBack, profile }) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answers, setAnswers] = useState<Record<number, string>>({});
