            <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mt-1">Syllabus Aligned AI</p>
          </div>
        </div>
        <select 
          value={activeSubject}
          onChange={(e) => setActiveSubject(e.target.value)}
          className="text-[10px] font-black text-emerald-700 bg-emerald-50 border-2 border-emerald-100 rounded-full px-3 py-1.5 outline-none appearance-none cursor-pointer"
        >
          {Array.from(new Set([...profile.selectedSubjects.WAEC, ...profile.selectedSubjects.NECO])).map(s => (
            <option key={s} value={s}>{s.toUpperCase()}</option>
          ))}
        </select>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-20 custom-scrollbar">
        {isLoadingQuestions ? (
          <div className="flex flex-col items-center justify-center py-24 space-y-6">
            <div className="relative">
              <Loader2 className="w-12 h-12 text-emerald-600 animate-spin" />
              <div className="absolute inset-0 flex items-center justify-center">
                <Target size={14} className="text-emerald-400" />
              </div>
            </div>
            <div className="text-center">
              <p className="text-sm font-black text-slate-900 uppercase tracking-widest">Generating Practice Set</p>
              <p className="text-[11px] text-slate-400 font-medium mt-1">Curating {activeSubject} questions...</p>
            </div>
          </div>
        ) : !currentResult ? (
          <div className="space-y-6 max-w-lg mx-auto">
            <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-xl relative overflow-hidden group">
              <div className="absolute -top-10 -right-10 w-40 h-40 bg-emerald-50 rounded-full blur-3xl opacity-50 group-hover:scale-110 transition-transform"></div>
              <div className="flex items-center gap-3 mb-6">
                <span className="bg-emerald-600 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-tighter">Task {currentIdx + 1} of {questions.length}</span>
                <span className="text-slate-300 font-bold">|</span>
                <span className="text-slate-400 text-[10px] font-black uppercase tracking-widest">{currentQ?.examType} THEORY</span>
              </div>
              <h3 className="text-xl font-black text-slate-900 leading-snug mb-4">{currentQ?.text}</h3>
              <div className="flex items-center gap-2 text-emerald-600 bg-emerald-50 w-fit px-3 py-1.5 rounded-xl border border-emerald-100">
                <Info size={12} />
                <span className="text-[10px] font-bold">Grade based on official marking schemes.</span>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between px-2">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Type your response</h4>
