          <div className="space-y-6 max-w-lg mx-auto animate-in fade-in zoom-in-95 duration-500">
            {/* Report Header */}
            <div className={`p-8 rounded-[40px] border-2 shadow-2xl text-center space-y-4 relative overflow-hidden transition-all ${getScoreColor(currentResult.score)}`}>
              <Sparkles className="absolute top-4 right-4 w-10 h-10 opacity-20" />
              <div className="inline-flex items-center justify-center w-32 h-32 rounded-full border-8 border-white bg-white/50 text-slate-900 font-black text-5xl shadow-lg relative z-10">
                {currentResult.score}%
              </div>
              <div className="relative z-10">
                <h3 className="text-2xl font-black uppercase tracking-tight">Examiner's Grade</h3>
                <p className="text-sm mt-3 leading-relaxed font-bold opacity-80">{currentResult.feedback}</p>
              </div>
              <div className="absolute bottom-0 left-0 w-full h-2 bg-white/20">
                 <div className="h-full bg-white transition-all duration-1000" style={{ width: `${currentResult.score}%` }}></div>
              </div>
