               <p className={`text-[13px] leading-relaxed font-bold ${color === 'slate' ? 'text-slate-300' : 'text-slate-600'}`}>{item.replace(/^\d\.[ \t]*/, '')}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

